Object.assign(ACTS.stars,{l4:X('เฝ้าดูดาวและจดลางบอกเหตุ','Watch the stars and note the omens'),c4:X('นั่งดูดาวบนหลังคาบ้าน','Watch the stars from the roof')});
Object.assign(ACTS.child,{l4:X('ดูแลเด็กและคนป่วยในบ้าน','Care for the children and the sick at home')});
const ACT4=['sow','herd','fish','herb','child','rest','story','trade','build','stars','job','school','write','read','brew','temple','garden'];
Object.assign(INV,{beer:{n:X('เบียร์ในโถ','jars of beer'),v:1},dates:{n:X('อินทผลัมแห้ง','dried dates'),v:1},bronze:{n:X('ของสำริด','bronze pieces'),v:3}});
const hireNote=X('จดหมายในเมโสโปเตเมียเขียนบนแผ่นดินเหนียวขนาดฝ่ามือ แล้วห่อด้วยซองดินเหนียวที่เขียนชื่อผู้รับและประทับตรา คนที่อ่านไม่ออกจ้างอาลักษณ์เขียนและอ่านให้ ส่วนกระดาษปาปิรุสเป็นวัสดุของอียิปต์ มาใช้ในเมโสโปเตเมียน้อยมาก','Mesopotamian letters were written on palm-sized clay tablets, then wrapped in a clay envelope bearing the addressee’s name and a seal. People who could not read hired a scribe to write and read for them. Papyrus was Egypt’s writing material and was rarely used in Mesopotamia.');
const canWrite=S=>S.lit>=35||S.ag>=1;
const NOWRITE=X('ต้องอ่านเขียนได้ หรือมีเงินหนึ่งเชเคิลไว้จ้างอาลักษณ์','You must read and write, or have a shekel to hire a scribe');
function doWrite(S,k){if(S.lit>=35){S.tabN++;S.tabK[k]=(S.tabK[k]||0)+1;return 1}S.ag=Math.max(0,S.ag-1);return 0}
const wOpt=(l,run)=>Object.assign(opt(l,run),{lockF:S=>!canWrite(S),lockT:NOWRITE});

const DEC4=[
/* ----- childhood ----- */
{id:'c4_name',deck:'child',w:3,ch:4,a:[5,9],t:X('ความหมายของชื่อคุณ','What your name means'),
 xf:S=>X('แม่เล่าว่าชื่อ '+S.nm4.th+' ของคุณแปลว่า '+S.nm4.mean.th+' ทุกคนในเมืองมีชื่อที่มีความหมาย และเมื่อคุณรับปันส่วนหรือทำสัญญา อาลักษณ์จะเขียนชื่อนี้ลงบนดินเหนียว','Your mother tells you that your name, '+S.nm4.l+', means '+S.nm4.mean.en+'. Everyone in the city has a name that means something, and when you receive rations or make a contract, a scribe writes it in clay.'),
 n:X('ชื่อชาวสุเมเรียนและอัคคาเดียนส่วนใหญ่มีความหมาย มักเอ่ยถึงเทพ เช่น อูร์-นันเช แปลว่า “ชายผู้รับใช้เทพีนันเช” เรารู้จักชื่อคนจริงนับหมื่นชื่อจากแผ่นดินเหนียว อักษรรูปลิ่มของชื่อคุณในเกมเป็นการสะกดแบบประมาณ อาลักษณ์จริงสะกดชื่อเดียวกันได้หลายแบบ','Most Sumerian and Akkadian names had meanings and often named a god: Ur-Nanshe means “servant of the goddess Nanshe”. We know tens of thousands of real people’s names from clay tablets. The cuneiform spelling of your name in this game is approximate; real scribes spelled the same name in several ways.'),
 o:[opt(X('ภูมิใจในชื่อของตัวเอง','Be proud of your name'),S=>{fx({b:3,so:2});return X('คุณพูดชื่อตัวเองให้ทุกคนฟังทั้งวัน','You tell everyone your name all day long.')}),
    opt(X('ถามว่าเทพองค์นั้นเป็นใคร','Ask who that god is'),S=>{fx({kn:4});return X('แม่พาคุณไปยืนดูรูปเคารพที่ลานวิหาร และเล่าเรื่องของเทพองค์นั้นจนมืด','Your mother takes you to the temple courtyard to look at the god’s image, and tells you stories until dark.')}),
    opt(X('ถามว่าพ่อชื่อว่าอะไร และแปลว่าอะไร','Ask what your father’s name means'),S=>{fx({b:3,kn:2});return X('พ่อชื่อ '+S.nm4.fa.th+' แปลว่า '+S.nm4.fa.mean.th+' คุณจำชื่อของพ่อ ปู่ และทวดได้ครบ','Your father is '+S.nm4.fa.l+', which means '+S.nm4.fa.mean.en+'. You learn the names of your father, grandfather and great-grandfather by heart.')})]},
{id:'c4_edubba',deck:'child',w:4,ch:4,a:[6,10],cond:S=>!!S.schOK,t:X('วันแรกที่บ้านแผ่นจารึก','First day at the tablet house'),
 x:X('ครูให้คุณกดปลายก้านอ้อลงบนดินเหนียวเปียก เป็นลิ่มเล็กๆ ซ้ำไปซ้ำมาทั้งวัน เด็กโตเรียกครูว่า “พ่อของบ้านแผ่นจารึก”','The teacher has you press the tip of a reed into wet clay, making little wedges, over and over all day. The older pupils call the teacher “father of the tablet house”.'),
 n:X('โรงเรียนอาลักษณ์เรียกว่า เอดุบบา แปลว่า “บ้านแผ่นจารึก” นักเรียนเริ่มจากลากลิ่ม คัดรายการเครื่องหมาย รายการคำ สุภาษิต และในที่สุดวรรณกรรม นักเรียนส่วนใหญ่เป็นลูกชายตระกูลมีฐานะ แต่ก็มีผู้หญิงที่เป็นอาลักษณ์ด้วย','The scribal school was the edubba, “tablet house”. Pupils began with wedges, then copied sign lists, word lists, proverbs and finally literature. Most were sons of well-off families, but there were women scribes too.'),
 o:[opt(X('คัดลอกอย่างตั้งใจทุกลิ่ม','Copy every wedge with care'),S=>{S.lit+=6;fx({kn:3});return X('ลายมือของคุณยังโย้ แต่ครูพยักหน้า','Your hand still wobbles, but the teacher nods.')}),
    opt(X('แอบวาดรูปลาไว้ที่มุมแผ่น','Secretly draw a donkey in the corner'),S=>{fx({b:4});if(rnd()<.5){fx({h:-2});return X('ครูเห็นเข้า คุณโดนไม้เรียว แต่เพื่อนทั้งห้องหัวเราะ','The teacher sees it. You get the cane, but the whole class laughs.')}return X('ไม่มีใครเห็น แผ่นนั้นถูกขยำกลับเป็นก้อนดินตอนเย็น','No one sees. In the evening the tablet is squashed back into a lump of clay.')}),
    opt(X('ถามว่าเครื่องหมายแต่ละตัวหมายถึงอะไร','Ask what each sign means'),S=>{S.lit+=4;fx({kn:5});return X('ครูบอกว่าเครื่องหมายเดียวกันอาจอ่านได้หลายเสียง คุณปวดหัวแต่สนุก','The teacher says one sign can be read several ways. Your head aches, but you love it.')})]},
{id:'c4_cane',deck:'child',w:3,ch:4,a:[7,12],cond:S=>!!S.schOK&&S.done.c4_edubba!=null,t:X('ไม้เรียว','The cane'),
 x:X('วันนี้คุณมาสาย เขียนผิด และพูดโดยไม่ได้รับอนุญาต ผู้คุมประตู ผู้คุมระเบียบ และครูภาษาสุเมเรียน ผลัดกันตีคุณทีละคน','Today you were late, made mistakes and spoke without permission. The door-keeper, the hall monitor and the Sumerian teacher each cane you in turn.'),
 n:X('งานเขียนสุเมเรียนที่นักวิชาการเรียกว่า “วันเรียน” อายุราว 4,000 ปี เล่าเรื่องนักเรียนที่ถูกตีหลายครั้งในวันเดียว พ่อจึงเชิญครูมากินข้าว ให้เสื้อผ้าใหม่และแหวน หลังจากนั้นครูก็ชมเด็กคนนั้น นักเรียนรุ่นหลังคัดลอกเรื่องนี้กันมาก','A Sumerian composition scholars call “Schooldays”, about 4,000 years old, tells of a pupil caned many times in one day. His father invites the teacher to dinner and gives him a new robe and a ring, after which the teacher praises the boy. Later pupils copied it often.'),
 o:[opt(X('เล่าให้พ่อฟัง','Tell your father'),S=>{if(S.ag>=1)S.ag--;fx({b:3,lit:3});return X('พ่อเชิญครูมากินข้าว ให้เสื้อคลุมใหม่และแหวนหนึ่งวง วันต่อมาครูชมว่าคุณเป็นเด็กเก่ง','Your father invites the teacher to dinner and gives him a new robe and a ring. The next day the teacher calls you a fine pupil.')}),
    opt(X('ฝึกเขียนตอนกลางคืนจนไม่ผิดอีก','Practise at night until you stop making mistakes'),S=>{S.lit+=5;fx({h:-2,kn:3});return X('นิ้วของคุณเปื้อนดินจนนอนหลับ แต่สัปดาห์ต่อมาไม่มีใครตีคุณอีก','You fall asleep with clay on your fingers, but the next week no one canes you.')}),
    opt(X('หนีไปเล่นน้ำที่คลอง','Run off to swim in the canal'),S=>{S.lit=Math.max(0,S.lit-3);fx({b:5,h:2});return X('น้ำเย็นสบาย พรุ่งนี้คุณจะโดนหนักกว่าเดิม','The water is cool. Tomorrow will be worse.')})]},
{id:'c4_noschool',deck:'child',w:3,ch:4,a:[6,10],cond:S=>!S.schOK&&S.cls==='free',t:X('อยากเรียนเขียน','Wanting to learn to write'),
 x:X('ทุกเช้าคุณเห็นลูกบ้านใหญ่เดินถือแผ่นดินเหนียวไปบ้านแผ่นจารึก พ่อบอกว่าค่าครูแพงเกินกว่าบ้านเราจะจ่ายได้','Every morning you see children from the big houses carrying clay tablets to the tablet house. Your father says the teacher costs more than your family can pay.'),
 n:X('การรู้หนังสือในเมโสโปเตเมียมีน้อยมาก อาจไม่ถึงหนึ่งในร้อยคน การเรียนใช้เวลาหลายปีเพราะต้องจำเครื่องหมายหลายร้อยตัว คนส่วนใหญ่จ้างอาลักษณ์เมื่อต้องเขียนอะไร','Literacy in Mesopotamia was very rare, perhaps fewer than one person in a hundred. Learning took years because hundreds of signs had to be memorised; most people hired a scribe when something had to be written.'),
 o:[opt(X('อ้อนพ่อแม่ทุกวัน','Beg your parents every day'),S=>{if(rnd()<.35){S.schOK=1;fx({b:2});return X('แม่ขายผ้าทอสองผืนเพื่อจ่ายค่าครู คุณได้ไปเรียนแล้ว','Your mother sells two woven cloths to pay the teacher. You are going to school.')}fx({b:-2});return X('พ่อเงียบไปนาน แล้วส่ายหน้า','Your father is silent a long time, then shakes his head.')}),
    opt(X('แอบนั่งฟังอยู่ข้างกำแพงโรงเรียน','Sit and listen outside the school wall'),S=>{S.lit+=5;fx({kn:3});return X('คุณจำเครื่องหมายได้สิบกว่าตัวจากเสียงท่องของเด็กข้างใน','From the chanting inside you learn a dozen signs.')}),
    opt(X('ตั้งใจเรียนงานของพ่อแทน','Learn your father’s work instead'),S=>{fx({cr:4,sv:3});return X('มือของคุณจะรู้จักงาน แม้จะไม่รู้จักตัวอักษร','Your hands will know the work, even if they never know the signs.')})]},
{id:'c4_beerbread',deck:'child',w:2,ch:4,t:X('ขนมปังเบียร์','Beer bread'),
 x:X('แม่อบขนมปังบาปปีร์ บี้ใส่โถพร้อมข้าวบาร์เลย์งอก แล้วรอให้มันปุดๆ เป็นฟองเอง','Your mother bakes bappir bread, crumbles it into a jar with sprouted barley, and waits for it to bubble on its own.'),
 n:X('ชาวเมโสโปเตเมียดื่มเบียร์ทุกวัน เด็กก็ดื่มเบียร์อ่อน คนงานได้รับเบียร์เป็นส่วนหนึ่งของค่าจ้าง ร่องรอยเคมีของเบียร์ข้าวบาร์เลย์ที่เก่าแก่ที่สุดชิ้นหนึ่งพบที่โกดินเตเป ในอิหร่าน อายุราว 5,000 ปี','Mesopotamians drank beer every day; children drank weak beer, and workers received beer as part of their wages. Some of the oldest chemical traces of barley beer come from Godin Tepe in Iran, about 5,000 years old.'),
 o:[opt(X('แอบชิมก่อนใคร','Sneak a taste first'),S=>{fx({b:3});return X('มันเปรี้ยวจนคุณหน้าย่น แม่หัวเราะจนต้องวางทัพพี','It is so sour your face screws up. Your mother laughs so hard she drops the ladle.')}),
    opt(X('ช่วยคนโถทุกวัน','Help stir the jar every day'),S=>{fx({cr:4});return X('คุณเริ่มรู้ว่าวันไหนเบียร์ใกล้ได้ จากกลิ่นของมัน','You start to tell from the smell when the beer is nearly ready.')}),
    opt(X('ถามว่าทำไมมันเป็นฟองเอง','Ask why it bubbles by itself'),S=>{fx({kn:4});return X('แม่บอกว่าเทพีนินกาซีทำให้มันเป็นแบบนั้น แล้วร้องเพลงของเทพีให้ฟัง','Your mother says the goddess Ninkasi makes it so, and sings you her song.')})]},
{id:'c4_seal',deck:'child',w:2,ch:4,a:[8,12],t:X('ตราประทับทรงกระบอก','A cylinder seal'),
 x:X('ปู่ให้ตราประทับหินทรงกระบอกเล็กๆ แก่คุณ เมื่อกลิ้งบนดินเหนียว มันกลายเป็นภาพคน สัตว์ และเทพยืนเรียงกันเป็นแถวยาว','Your grandfather gives you a small stone cylinder seal. Rolled across clay, it leaves a long row of people, animals and gods.'),
 n:X('ตราประทับทรงกระบอกใช้มาตั้งแต่ราว 3500 ปีก่อนคริสตกาล ทำหน้าที่เหมือนลายเซ็น ใช้ประทับสัญญา ปิดฝาโถ และปิดประตูห้องเก็บของ หลายคนห้อยไว้ที่คอ','Cylinder seals were used from about 3500 BCE. They worked like signatures, sealing contracts, jar stoppers and storeroom doors. Many people wore theirs on a cord around the neck.'),
 o:[opt(X('ห้อยไว้ที่คอ','Wear it around your neck'),S=>{fx({b:3});S.seal=1;return X('คุณกลิ้งมันบนก้อนดินทุกก้อนที่เจอ','You roll it over every lump of clay you find.')}),
    opt(X('ลองแกะลายตราของตัวเอง','Try carving your own design'),S=>{fx({cr:6});S.seal=2;return X('ตราแรกของคุณเป็นรูปลาที่ขาไม่เท่ากัน แต่มันเป็นของคุณคนเดียว','Your first seal shows a donkey with uneven legs, but it is yours alone.')})]},
{id:'c4_flood',deck:'child',w:2,ch:4,t:X('น้ำหลากฤดูใบไม้ผลิ','The spring flood'),
 x:X('หิมะบนภูเขาทางเหนือละลาย แม่น้ำขึ้นสูงตรงกับฤดูเก็บเกี่ยวพอดี ผู้ใหญ่ทุกคนวิ่งไปเสริมคันดิน','Snow melts in the northern mountains, and the river rises just at harvest time. Every adult runs to raise the levees.'),
 n:X('ต่างจากแม่น้ำไนล์ที่ท่วมเป็นเวลา แม่น้ำไทกริสและยูเฟรทีสท่วมในเดือนเมษายนถึงพฤษภาคม ตรงกับข้าวสุก และคาดเดายาก ชาวเมโสโปเตเมียจึงต้องขุดคลองและคันดินอยู่ตลอด และมีตำนานน้ำท่วมโลกหลายเรื่อง','Unlike the Nile’s regular flood, the Tigris and Euphrates rose in April and May, just as the grain ripened, and unpredictably. Mesopotamians had to dig canals and levees endlessly, and told many stories of a great flood.'),
 o:[opt(X('ช่วยขนอิฐดิบไปวางบนคันดิน','Help carry mud bricks to the levee'),S=>{fx({sv:3,b:3,h:-1});return X('ตอนเช้าคันดินยังอยู่ ทุ่งข้าวของครอบครัวคุณรอด','In the morning the levee holds; your family’s barley is saved.')}),
    opt(X('พาน้องๆ ขึ้นไปบนหลังคา','Take the little ones up to the roof'),S=>{fx({so:3,b:2});return X('คุณนั่งกอดน้องอยู่บนหลังคาทั้งคืน ฟังเสียงน้ำไหล','You sit on the roof all night holding them, listening to the water.')})]},
{id:'c4_tokens',deck:'child',w:3,ch:4,cond:S=>era4(S.ya)==='uruk',t:X('เบี้ยดินเผา','Clay tokens'),
 x:X('คนเลี้ยงแกะนับแกะด้วยเบี้ยดินเผาเม็ดเล็ก แกะหนึ่งตัวต่อหนึ่งเม็ด แล้วปิดเบี้ยทั้งหมดไว้ในลูกบอลดินเหนียว เพื่อจะได้นับซ้ำตอนส่งคืน','The shepherd counts sheep with little clay tokens, one token for each sheep, and seals them all inside a clay ball so they can be checked when the flock comes back.'),
 n:X('นักโบราณคดีเดนิส ชมันด์-เบสเซอรา เสนอว่าตัวอักษรรูปลิ่มพัฒนามาจากเบี้ยนับของแบบนี้ เมื่อคนเริ่มกดรูปเบี้ยไว้บนผิวลูกบอลดินแทนการเปิดดู แนวคิดนี้มีผู้เห็นด้วยมากแต่ก็ยังถกเถียงกันอยู่','The archaeologist Denise Schmandt-Besserat proposed that cuneiform grew out of counting tokens like these, once people began pressing the tokens’ shapes onto the outside of the clay balls instead of breaking them open. The idea is widely cited but still debated.'),
 o:[opt(X('ช่วยนับเบี้ย','Help count the tokens'),S=>{fx({kn:4});return X('คุณนับได้ถูกทุกเม็ด คนเลี้ยงแกะให้เบี้ยรูปแกะไว้เล่นหนึ่งเม็ด','You count every one right, and the shepherd gives you a sheep-shaped token to keep.')}),
    opt(X('แอบทุบลูกบอลดินดูข้างใน','Secretly crack the clay ball to look inside'),S=>{fx({b:-2,kn:2});return X('เบี้ยร่วงกระจาย ทุกคนต้องนับแกะกันใหม่หมด','The tokens spill out, and everyone has to count the sheep all over again.')}),
    opt(X('กดรูปเบี้ยลงบนดินเหนียวแทน','Press the tokens’ shapes into clay instead'),S=>{S.lit+=3;fx({kn:5,p:1});return X('ผู้ใหญ่มองรอยบนดินแล้วพูดว่า แบบนี้ไม่ต้องทุบลูกบอลอีกเลย','The adults look at the marks and say: this way no one has to break the ball at all.')})]},
{id:'c4_lion',deck:'child',w:1.5,ch:4,a:[8,12],t:X('สิงโตในดงกก','A lion in the reeds'),
 x:X('ขณะคุณเฝ้าแกะริมบึง ดงกกไหวโดยไม่มีลม แล้วคุณเห็นแผงคอสีน้ำตาล','While you watch the sheep by the marsh, the reeds sway though there is no wind, and you see a tawny mane.'),
 n:X('สิงโตเคยอาศัยอยู่ในเมโสโปเตเมีย กษัตริย์อัสซีเรียและบาบิโลนโอ้อวดการล่าสิงโตในจารึกและภาพสลัก สิงโตเอเชียตัวสุดท้ายในอิรักหายไปในศตวรรษที่ 20','Lions once lived in Mesopotamia; Assyrian and Babylonian kings boasted of lion hunts in inscriptions and reliefs. The last Asiatic lions in Iraq vanished in the 20th century.'),
 o:[opt(X('ตะโกนและตีหม้อให้ดัง','Shout and bang a pot'),S=>{if(rnd()<.7){fx({p:3,b:3});return X('สิงโตถอยกลับเข้าดงกก ผู้ใหญ่ชมว่าคุณกล้า','The lion slinks back into the reeds. The adults call you brave.')}if(S.herd.sheep)S.herd.sheep--;fx({h:-6});return X('สิงโตคาบแกะไปหนึ่งตัว และกรงเล็บถากแขนคุณ','The lion takes a sheep, and its claws graze your arm.')}),
    opt(X('ต้อนแกะหนีกลับบ้าน','Drive the sheep home'),S=>{fx({sv:3});return X('คุณกลับถึงบ้านพร้อมแกะครบทุกตัว หัวใจยังเต้นแรง','You get home with every sheep, heart still pounding.')})]},
/* ----- youth ----- */
{id:'y4_proverb',deck:'youth',w:3,ch:4,cond:S=>S.lit>=20,t:X('คัดลอกสุภาษิต','Copying proverbs'),
 x:X('วันนี้ครูให้คัดสุภาษิตสุเมเรียนสามบท แล้วให้เลือกหนึ่งบทไปท่องหน้าห้อง','Today the teacher sets three Sumerian proverbs to copy, and you must recite one before the class.'),
 n:X('สุภาษิตสุเมเรียนหลายร้อยบทรอดมาเพราะนักเรียนอาลักษณ์คัดลอกซ้ำๆ ในเกมแปลความหมายอย่างคร่าวๆ','Hundreds of Sumerian proverbs survive because scribal pupils copied them again and again; the game paraphrases them loosely.'),
 o:[opt(X('“มิตรภาพอยู่ได้หนึ่งวัน ความเป็นญาติอยู่ได้ตลอดไป”','“Friendship lasts a day; kinship lasts forever.”'),S=>{S.lit+=3;fx({b:3});return X('ครูบอกว่าบทนี้คนชอบกันมาก แล้วถามว่าคุณเห็นด้วยไหม','The teacher says this one is a favourite, and asks whether you agree.')}),
    opt(X('“อาลักษณ์ที่มือไวเท่าปาก นั่นแหละอาลักษณ์”','“A scribe whose hand keeps up with the mouth: now that is a scribe!”'),S=>{S.lit+=5;fx({kn:2});return X('คุณเขียนเร็วขึ้นทุกวัน อยากเป็นอาลักษณ์แบบนั้น','You write faster every day, wanting to be that scribe.')}),
    opt(X('“คนที่มีเงินมากอาจสุขใจ คนที่ไม่มีอะไรเลยนอนหลับสบาย”','“Who has much silver may be happy; who has nothing can sleep.”'),S=>{S.lit+=3;fx({kn:3});return X('เพื่อนๆ หัวเราะ แต่ครูมองคุณนานกว่าปกติ','Your friends laugh, but the teacher looks at you a long while.')})]},
{id:'y4_math',deck:'youth',w:2,ch:4,cond:S=>S.lit>=30&&['ur3','ob','nb'].includes(era4(S.ya)),t:X('คำนวณฐานหกสิบ','Counting in sixties'),
 x:X('ครูให้โจทย์: ทุ่งนากว้าง 30 ยาว 40 ถ้าลากเส้นทแยงมุมจะยาวเท่าไร','The teacher sets a problem: a field 30 wide and 40 long. How long is the diagonal?'),
 n:X('ชาวบาบิโลนนับเลขฐานหกสิบ เราจึงยังมี 60 นาทีในหนึ่งชั่วโมงและ 360 องศาในวงกลม แผ่นจารึกพลิมพ์ตัน 322 ราว 1800 ปีก่อนคริสตกาล มีตารางตัวเลขที่ตรงกับสิ่งที่เรียกภายหลังว่าทฤษฎีบทพีทาโกรัส ก่อนพีทาโกรัสกว่าพันปี','Babylonians counted in base sixty, which is why we still have 60 minutes in an hour and 360 degrees in a circle. The tablet Plimpton 322, about 1800 BCE, lists numbers matching what was later called the Pythagorean theorem, more than a thousand years before Pythagoras.'),
 o:[opt(X('คิดออกมาว่า 50','Work it out: 50'),S=>{S.lit+=4;fx({kn:6,p:2});return X('ครูยิ้ม แล้วให้โจทย์ที่ยากกว่าเดิมสิบข้อ','The teacher smiles, and sets you ten harder ones.')}),
    opt(X('ลอกคำตอบเพื่อน','Copy your friend’s answer'),S=>{fx({b:2,kn:-1});return X('คำตอบของเพื่อนผิด คุณสองคนผิดเหมือนกันทุกตัวเลข','Your friend’s answer is wrong, and the two of you are wrong in exactly the same way.')})]},
{id:'y4_marry',deck:'youth',w:5,ch:4,a:[15,19],cond:S=>!S.partner&&!S.nad,t:X('สัญญาแต่งงาน','A marriage contract'),
 xf:S=>S.sex==='f'?X('ครอบครัวของชายคนหนึ่งมาสู่ขอ นำเงินสินสอดมาวางให้พ่อของคุณ ส่วนครอบครัวคุณต้องเตรียมสินเดิมไปกับคุณ อาลักษณ์รอเขียนสัญญาอยู่','A man’s family comes to ask for you, setting a bride-price before your father; your family must prepare a dowry to go with you. A scribe waits to write the contract.'):X('พ่อบอกว่าได้คุยกับครอบครัวหนึ่งไว้แล้ว ถ้าตกลง คุณต้องนำเงินสินสอดไปให้ และอาลักษณ์จะเขียนสัญญาแต่งงาน','Your father says he has spoken with a family. If you agree, you must bring a bride-price, and a scribe will write the marriage contract.'),
 n:X('การแต่งงานในเมโสโปเตเมียมักจัดโดยครอบครัว ฝ่ายชายให้สินสอด ฝ่ายหญิงนำสินเดิมมา ซึ่งยังเป็นของภรรยา หลายคู่ทำสัญญาเป็นลายลักษณ์อักษร ระบุแม้กระทั่งค่าปรับเมื่อหย่า','Mesopotamian marriages were usually arranged by families. The groom’s side paid a bride-price and the bride brought a dowry that remained hers. Many couples had written contracts, some even setting the penalty for divorce.'),
 o:[opt(X('ตกลงตามที่ครอบครัวเลือก','Agree to the family’s choice'),S=>{S.partner=1;S.nameTab=1;fx({b:5});ms(X('แต่งงาน มีสัญญาบนแผ่นดินเหนียว','Married, with a contract in clay'));return X('ชื่อของคุณสองคนถูกเขียนลงบนสัญญา พร้อมชื่อพยานห้าคน แล้วนำไปเผาให้แข็ง','Both your names are written into the contract with the names of five witnesses, and it is baked hard.')}),
    opt(X('ขอเลือกคนที่ชอบเอง','Ask to choose someone you love'),S=>{if(rnd()<.5){S.partner=1;fx({b:8});ms(X('แต่งงานกับคนที่เลือกเอง','Married someone you chose'));return X('พ่อบ่นอยู่สามวัน แล้วยอมไปสู่ขอให้','Your father grumbles for three days, then goes to ask for you.')}fx({b:-4});return X('ครอบครัวไม่ยอม คุณต้องรอต่อไป','The families refuse. You will have to wait.')}),
    opt(X('ขอรอไปก่อน','Ask to wait'),S=>{fx({kn:2});return X('พ่อถอนใจ แต่ไม่บังคับ','Your father sighs, but does not force you.')})]},
{id:'y4_corvee',deck:'youth',w:2.5,ch:4,a:[15,19],cond:S=>S.cls!=='elite',t:X('ถูกเกณฑ์ไปขุดคลอง','Called up to dig canals'),
 x:X('เจ้าหน้าที่ของวังมาเรียกชื่อคุณจากแผ่นจารึก ทุกบ้านต้องส่งคนไปขุดลอกคลองใหญ่หนึ่งเดือน','A palace official calls your name from a tablet. Every household must send someone to clear the great canal for a month.'),
 n:X('ระบบชลประทานต้องการแรงงานมหาศาล รัฐเกณฑ์แรงงานจากครัวเรือนเป็นช่วงๆ จ่ายเป็นข้าวบาร์เลย์และเบียร์ คนมีเงินบางคนจ้างคนอื่นไปแทน','Irrigation needed enormous labour. The state called up workers from households for set periods, paid in barley and beer; some who could afford it paid a substitute.'),
 o:[opt(X('ไปขุดคลอง','Go and dig'),S=>{fx({h:-4,sv:3,so:2});return X('คุณแบกตะกร้าโคลนทั้งเดือน กลับบ้านมาพร้อมไหล่ที่แข็งแรงขึ้นและเพื่อนใหม่หลายคน','You carry baskets of mud for a month and come home with stronger shoulders and new friends.')}),
    Object.assign(opt(X('จ่ายเงินจ้างคนไปแทน','Pay someone to go in your place'),S=>{S.ag-=2;fx({b:-1});return X('คนที่ไปแทนคุณเป็นชายจนจากหมู่บ้านริมบึง','The man who goes in your place is a poor man from a marsh village.')}),{lockF:S=>S.ag<2,lockT:X('ต้องมีเงินสองเชเคิล','You need two shekels')})]},
{id:'y4_tavern',deck:'youth',w:2,ch:4,a:[16,19],t:X('เสียงกระซิบในร้านเบียร์','Whispers in the tavern'),
 x:X('ในร้านเบียร์ ชายกลุ่มหนึ่งกระซิบกันว่าจะลอบทำร้ายเจ้าหน้าที่เก็บภาษี เจ้าของร้านมองคุณ เพราะคุณได้ยินด้วย','In the tavern a group of men whisper about attacking the tax collector. The tavern keeper looks at you, because you heard too.'),
 n:X('กฎหมายฮัมมูราบีข้อ 109 กำหนดว่า ถ้าเจ้าของร้านเบียร์รู้ว่ามีคนร้ายวางแผนกันในร้านแล้วไม่จับส่งวัง เจ้าของร้านต้องถูกประหาร มีกฎหมายหลายข้อเกี่ยวกับร้านเบียร์ ซึ่งมักมีผู้หญิงเป็นเจ้าของ','Hammurabi’s law 109 says that if criminals plot in a tavern and the tavern keeper does not seize them and bring them to the palace, the keeper shall be put to death. Several laws concern taverns, which were often run by women.'),
 o:[opt(X('ไปแจ้งเจ้าหน้าที่','Report it'),S=>{fx({p:4,b:-2});return X('ชายกลุ่มนั้นถูกจับ เจ้าของร้านขอบคุณคุณ แต่บางคนในย่านเลิกทักคุณ','The men are seized. The tavern keeper thanks you, but some in the quarter stop greeting you.')}),
    opt(X('ทำเป็นไม่ได้ยิน','Pretend you heard nothing'),S=>{fx({b:1});return X('คุณไม่เคยรู้ว่าเรื่องนั้นจบอย่างไร','You never learn how it ended.')})]},
{id:'y4_naditu',deck:'youth',w:3,ch:4,a:[14,19],cond:S=>S.sex==='f'&&['ob','ur3'].includes(era4(S.ya))&&(S.cls==='elite'||S.cls==='free')&&!S.partner,t:X('เป็นนาดิตูของเทพชามาช','To become a naditu of Shamash'),
 x:X('พ่ออยากส่งคุณไปเป็นนาดิตูของเทพสุริยะชามาช คุณจะไม่แต่งงานและไม่มีลูก อยู่ในเขตปิดของวิหาร แต่จะได้ที่ดินเป็นของตัวเอง ทำธุรกิจ และให้กู้ได้','Your father wants to dedicate you as a naditu of the sun god Shamash. You would not marry or have children, and would live in the temple cloister, but you would hold land of your own, do business and lend silver.'),
 n:RNOTE4.sip,
 o:[opt(X('ยอมเป็นนาดิตู','Become a naditu'),S=>{S.nad=1;S.ag+=8;S.schOK=1;S.lit+=6;fx({p:5,b:-2});ms(X('เป็นนาดิตูแห่งเทพชามาช','Became a naditu of Shamash'));return X('คุณย้ายเข้าเขตวิหารพร้อมสินเดิมเป็นที่ดินและเงิน เพื่อนบ้านใหม่ของคุณเป็นหญิงที่ทำสัญญาเก่งที่สุดในเมือง','You move into the cloister with a dowry of land and silver. Your new neighbours are the shrewdest contract-makers in the city.')}),
    opt(X('ขอแต่งงานแทน','Ask to marry instead'),S=>{fx({b:2});return X('พ่อยอม แต่บอกว่าครอบครัวจะเสียโอกาสดีๆ ไป','Your father agrees, but says the family is losing a fine chance.')})]},
{id:'y4_levy',deck:'youth',w:2.5,ch:4,a:[16,19],cond:S=>S.sex==='m'&&['ed','akk','ur3','nb'].includes(era4(S.ya)),t:X('สงครามระหว่างนคร','War between cities'),
 xf:S=>S.rg==='lag'&&era4(S.ya)==='ed'?X('ทหารจากเมืองอุมมาย้ายหลักเขตและไถนาในเขตของลากัชอีกแล้ว ผู้ครองนครเรียกชายหนุ่มทุกบ้านไปรบ','Soldiers from Umma have moved the boundary stone and ploughed Lagash’s fields again. The ruler calls up young men from every house.'):X('พระราชาเรียกชายหนุ่มทุกบ้านไปรบ ทุกคนได้หอก โล่ไม้ และขนมปังสามก้อน','The king calls up young men from every house. Each gets a spear, a wooden shield and three loaves of bread.'),
 n:X('ศิลาจารึกแห่งนกแร้ง ราว 2450 ปีก่อนคริสตกาล แสดงทหารลากัชเดินเป็นแถวแน่นหลังโล่ ถือหอกยื่นไปข้างหน้า นับเป็นภาพกองทัพจัดแถวที่เก่าที่สุดภาพหนึ่ง สงครามระหว่างลากัชกับอุมมาเรื่องที่ดินชายแดนยืดเยื้อนับร้อยปี','The Stele of the Vultures, about 2450 BCE, shows Lagash soldiers marching in a tight block behind their shields with spears thrust forward, one of the oldest images of an organised army. The Lagash–Umma border war dragged on for about a century.'),
 o:[opt(X('ไปรบ','Go to war'),S=>{if(rnd()<.6){fx({p:5,sv:3});S.ag+=2;return X('คุณกลับมาพร้อมของที่ยึดได้และรอยแผลเป็นที่ไม่มีใครเห็น','You come home with plunder and a scar no one can see.')}S.inj=1;fx({h:-14});return X('หอกของศัตรูแทงต้นขาคุณ เพื่อนต้องแบกคุณกลับบ้าน','An enemy spear pierces your thigh; your friends carry you home.')}),
    Object.assign(opt(X('จ่ายเงินให้คนอื่นไปแทน','Pay someone to go in your place'),S=>{S.ag-=3;fx({b:-2});return X('คุณไม่ได้ไปรบ แต่คนในย่านรู้ว่าทำไม','You stay home, and the quarter knows why.')}),{lockF:S=>S.ag<3,lockT:X('ต้องมีเงินสามเชเคิล','You need three shekels')})]},
{id:'y4_straw',deck:'youth',w:2,ch:4,t:X('หลอดดูดเบียร์','The drinking straws'),
 x:X('ในงานเทศกาล ทุกคนนั่งล้อมโถเบียร์ใบใหญ่ใบเดียว เสียบหลอดยาวลงไปดูดพร้อมกัน','At the festival everyone sits around one great jar of beer, dipping long straws into it to drink together.'),
 n:X('เบียร์เมโสโปเตเมียมีกากข้าวลอยอยู่ คนจึงดื่มด้วยหลอดยาว ในหลุมศพของราชินีปูอาบีที่อูร์ พบหลอดดูดเบียร์ทำด้วยทองและลาพิสลาซูลี ภาพบนตราประทับหลายชิ้นแสดงคนดื่มเบียร์จากโถเดียวกัน','Mesopotamian beer had husks floating in it, so people drank through long straws. Queen Puabi’s tomb at Ur held a drinking straw of gold and lapis lazuli, and many seals show people drinking from a shared jar.'),
 o:[opt(X('ดูดให้นานที่สุด','Drink as long as you can'),S=>{fx({b:4,h:-1});return X('ทุกคนเชียร์ แล้วคุณก็หลับไปข้างโถ','Everyone cheers, and then you fall asleep beside the jar.')}),
    opt(X('ร้องเพลงสรรเสริญเทพีนินกาซี','Sing the hymn to Ninkasi'),S=>{fx({so:4,b:3});return X('ทั้งวงร้องตาม เพลงนี้บอกวิธีหมักเบียร์ทีละขั้น','The whole circle joins in; the song tells how to brew beer step by step.')})]},
/* ----- adulthood ----- */
{id:'a4_loan',a:[20,55],w:2.5,ch:4,cond:S=>S.f<58&&!S.debt&&S.cls!=='slave',t:X('ยืมจากพ่อค้า','A loan from the merchant'),
 x:X('ปีนี้ข้าวไม่พอกิน พ่อค้าคนหนึ่งยินดีให้ยืมข้าวบาร์เลย์ ถ้าคุณลงชื่อในสัญญา คืนพร้อมดอกเบี้ยหนึ่งในสามหลังเก็บเกี่ยว','There is not enough grain this year. A merchant will lend you barley if you seal a contract to repay it with a third more after harvest.'),
 n:X('กฎหมายบาบิโลนเก่ากำหนดดอกเบี้ยสูงสุดราว 33 ส่วนในร้อยต่อปีสำหรับข้าวบาร์เลย์ และ 20 ส่วนในร้อยสำหรับเงิน หนี้เป็นเรื่องธรรมดามาก กษัตริย์บางองค์ประกาศ “มีชารุม” ยกหนี้ทั้งแผ่นดิน เพื่อไม่ให้คนกลายเป็นทาสหนี้มากเกินไป','Old Babylonian law capped interest at about 33 per cent a year on barley and 20 per cent on silver. Debt was very common, and some kings proclaimed a misharum, cancelling debts across the land so that too many people did not fall into debt slavery.'),
 o:[opt(X('ลงชื่อในสัญญายืม','Seal the loan contract'),S=>{S.debt=5;S.debtY=0;fx({f:14});return X('คุณกลิ้งตราประทับบนสัญญา ครอบครัวมีข้าวกินจนถึงฤดูเก็บเกี่ยว','You roll your seal across the contract. The family eats until harvest.')}),
    opt(X('ขายของในบ้าน','Sell things from the house'),S=>{const k=Object.keys(S.inv).find(k=>S.inv[k]>0);if(k){S.inv[k]--;fx({f:8});return X('คุณขาย'+invName(k)+'ไป ได้ข้าวพอประทังชีวิต','You sell your '+invName(k)+' and get enough grain to scrape by.')}fx({f:3,b:-2});return X('ในบ้านแทบไม่มีอะไรเหลือให้ขาย','There is almost nothing left in the house to sell.')}),
    opt(X('อดทนกินน้อยลง','Tighten your belts'),S=>{fx({h:-5,b:-2});return X('ทุกคนผอมลง แต่ไม่มีใครเป็นหนี้','Everyone grows thin, but no one is in debt.')})]},
{id:'a4_lend',a:[20,60],w:1.2,ch:4,cond:S=>S.ag>=4&&!S.lent&&S.ppl.some(p=>!p.dead&&p.age>=16&&p.k!=='partner'),t:X('ขอยืมเงิน','Asked for a loan'),
 xf:S=>{const p=S.ppl.find(p=>!p.dead&&p.age>=16&&p.k!=='partner');S.lentTo=p;return PX(p,'{p}มาขอยืมเงินสามเชเคิล บอกว่าจะคืนหลังเก็บเกี่ยว','{p} asks to borrow three shekels of silver, promising to repay after harvest.')},
 n:X('การให้ยืมเงินในเมโสโปเตเมียมักทำสัญญาบนแผ่นดินเหนียว มีพยาน และใส่ซองดินเหนียวที่เขียนข้อความซ้ำไว้ข้างนอก ถ้ามีข้อพิพาท ผู้พิพากษาจะทุบซองดูข้อความข้างใน ซึ่งไม่มีใครแก้ได้','Loans in Mesopotamia were often recorded on a clay tablet with witnesses, sealed in a clay envelope that repeated the text outside. In a dispute, the judges broke the envelope to read the inner text, which no one could have altered.'),
 o:[wOpt(X('ให้ยืม และทำสัญญาบนแผ่นดินเหนียว','Lend it, with a contract in clay'),S=>{const w=doWrite(S,'contract');S.ag-=3;S.lent={p:S.lentTo,a:S.age,c:1};return w?X('คุณเขียนสัญญาเอง พร้อมชื่อพยานสองคน แล้วห่อด้วยซองดินเหนียว','You write the contract yourself, with two witnesses, and wrap it in a clay envelope.'):X('คุณจ้างอาลักษณ์เขียนสัญญา พร้อมชื่อพยานสองคน','You hire a scribe to write the contract, with two witnesses.')}),
    opt(X('ให้ยืมโดยไม่ต้องมีสัญญา','Lend it on trust'),S=>{S.ag-=3;S.lent={p:S.lentTo,a:S.age,c:0};S.lentTo.tr=Math.min(100,S.lentTo.tr+8);return PX(S.lentTo,'{p}กอดคุณ และสัญญาว่าจะคืนแน่นอน','{p} embraces you and swears to repay.')}),
    opt(X('ปฏิเสธ','Refuse'),S=>{S.lentTo.tr-=8;return PX(S.lentTo,'{p}เดินกลับไปเงียบๆ','{p} walks away in silence.')})]},
{id:'a4_collect',a:[21,70],w:6,ch:4,cond:S=>S.lent&&!S.lent.done&&S.age-S.lent.a>=2,t:X('ทวงหนี้','Collecting the debt'),
 xf:S=>PX(S.lent.p,'สองปีผ่านไปแล้ว {p}ยังไม่คืนเงินสามเชเคิลที่ยืมไป และทำเป็นไม่เห็นคุณในตลาด','Two years have passed. {p} has not repaid the three shekels and pretends not to see you in the market.'),
 n:hireNote,
 o:[wOpt(X('เขียนจดหมายทวงบนแผ่นดินเหนียว','Write a demand letter on a clay tablet'),S=>{const p=S.lent.p;S.lent.done=1;doWrite(S,'letter');
      if(p.dead){return PX(p,'จดหมายไปถึงบ้านของ{p} แต่เขาเพิ่งจากไป ลูกชายของเขาคืนเงินให้หนึ่งเชเคิลด้วยความละอาย','The letter reaches {p}’s house, but he has just died. His son repays one shekel, ashamed.')}
      if(rnd()<.55+(p.tr-50)/200){S.ag+=4;p.tr=Math.max(0,p.tr-5);return PX(p,'จดหมายของคุณขึ้นต้นว่า “ถึง{p} คนที่ส่งสารนี้พูดว่า…” ไม่กี่วันต่อมา{p}ส่งเงินคืนมาพร้อมดอกเบี้ย','Your letter begins, “To {p}, thus says the sender…” A few days later {p} sends back the silver with interest.')}
      p.tr-=10;return PX(p,'{p}ส่งจดหมายตอบกลับมาว่าปีนี้ข้าวเสียหาย ขอผัดไปก่อน','{p} writes back that the harvest failed and begs for more time.')}),
    opt(X('ไปทวงถึงบ้านพร้อมพยาน','Go to the house with witnesses'),S=>{const p=S.lent.p;S.lent.done=1;if(!p.dead&&rnd()<.6){S.ag+=3;p.tr-=12;return PX(p,'ต่อหน้าพยาน {p}ยอมคืนเงิน แต่จะไม่ลืมความอับอายครั้งนี้','Before the witnesses {p} pays, but will not forget the shame.')}fx({b:-3});return X('คุณได้แต่คำสัญญาใหม่','All you get is a new promise.')}),
    Object.assign(opt(X('ฟ้องต่อผู้พิพากษา พร้อมแผ่นสัญญา','Take it to the judges, with the contract'),S=>{S.lent.done=1;S.ag+=4;fx({p:2});return X('ผู้พิพากษาทุบซองดินเหนียว อ่านข้อความข้างใน แล้วตัดสินให้คุณชนะ','The judges break the clay envelope, read the text inside and rule in your favour.')}),{lockF:S=>!S.lent.c,lockT:X('ต้องมีสัญญาบนแผ่นดินเหนียว','You need a contract in clay')}),
    opt(X('ยกหนี้ให้','Forgive the debt'),S=>{S.lent.done=1;S.lent.p.tr=Math.min(100,S.lent.p.tr+20);fx({b:4});return PX(S.lent.p,'{p}ร้องไห้ และจะไม่ลืมน้ำใจของคุณ','{p} weeps, and will never forget your kindness.')})]},
{id:'a4_eanasir',a:[22,60],w:4,ch:4,cond:S=>era4(S.ya)==='ob'&&(S.car==='smith'||S.car==='merchant'||S.ag>=5),t:X('ทองแดงคุณภาพแย่ของเอีย-นาซีร์','Ea-nasir’s bad copper'),
 x:X('คุณจ่ายเงินให้พ่อค้าชื่อเอีย-นาซีร์ เพื่อซื้อแท่งทองแดงที่มาทางเรือจากดิลมุน แต่ของที่ส่งมาเป็นทองแดงเกรดต่ำ และคนรับใช้ของเขาพูดกับคนของคุณอย่างหยาบคาย','You paid a merchant named Ea-nasir for copper ingots shipped from Dilmun. What arrives is poor copper, and his servant was rude to your man.'),
 n:X('ราว 1750 ปีก่อนคริสตกาล ชายชื่อนันนีเขียนจดหมายต่อว่าเอีย-นาซีร์แห่งอูร์ว่าส่งทองแดงคุณภาพแย่ และ “ท่านปฏิบัติต่อข้าอย่างดูหมิ่น” แผ่นจารึกนี้อยู่ที่บริติชมิวเซียม มักถูกเรียกว่าจดหมายร้องเรียนลูกค้าที่เก่าที่สุดในโลก ในบ้านของเอีย-นาซีร์ยังพบจดหมายต่อว่าเรื่องทองแดงอีกหลายแผ่น','About 1750 BCE a man named Nanni wrote to Ea-nasir of Ur complaining of poor copper and that he had been treated “with contempt”. The tablet, in the British Museum, is often called the world’s oldest customer complaint, and more complaint letters about copper were found in Ea-nasir’s house.'),
 o:[wOpt(X('เขียนจดหมายต่อว่าอย่างเผ็ดร้อน','Write a furious letter'),S=>{doWrite(S,'letter');S.eanasir=1;if(rnd()<.4){S.ag+=3;return X('คุณเขียนว่า “ท่านคิดว่าข้าเป็นใคร ถึงทำกับข้าเช่นนี้” ไม่กี่เดือนต่อมา เอีย-นาซีร์ส่งเงินคืนให้บางส่วน','You write: “Who do you take me for, to treat me like this?” Months later, Ea-nasir returns part of the silver.')}return X('คุณเขียนว่า “ท่านคิดว่าข้าเป็นใคร ถึงทำกับข้าเช่นนี้” เอีย-นาซีร์ไม่ตอบ จดหมายของคุณคงไปกองรวมกับแผ่นอื่นในบ้านเขา','You write: “Who do you take me for, to treat me like this?” Ea-nasir never answers. Your letter likely joins the pile in his house.')}),
    opt(X('ไปบ้านเขาพร้อมพยาน','Go to his house with witnesses'),S=>{if(rnd()<.5){S.ag+=2;return X('เอีย-นาซีร์ยิ้มเจื่อนๆ แล้วเปลี่ยนแท่งทองแดงให้สองแท่ง','Ea-nasir smiles weakly and swaps two of the ingots.')}fx({b:-3});return X('เขาไม่อยู่บ้าน คนรับใช้คนเดิมปิดประตูใส่หน้าคุณ','He is not home, and the same servant shuts the door in your face.')}),
    opt(X('ยอมรับ แล้วไม่ซื้อจากเขาอีก','Accept it, and never buy from him again'),S=>{fx({kn:2});return X('คุณบอกพ่อค้าทุกคนในตลาดว่าอย่าซื้อจากเอีย-นาซีร์','You tell every merchant in the market not to buy from Ea-nasir.')})]},
{id:'a4_law',a:[20,65],w:2.5,ch:4,cond:S=>['ob','nb'].includes(era4(S.ya))&&S.field,t:X('คันนาของเพื่อนบ้านพัง','The neighbour’s dike breaks'),
 x:X('เพื่อนบ้านไม่ยอมซ่อมคันนาของเขา คืนหนึ่งมันพัง น้ำทะลักเข้าท่วมข้าวบาร์เลย์ในนาของคุณ','Your neighbour never mended his dike. One night it breaks and water floods your barley.'),
 n:X('กฎหมายฮัมมูราบีข้อ 53 กำหนดว่า ถ้าใครละเลยไม่เสริมคันนาจนน้ำท่วมนาของคนอื่น คนนั้นต้องชดใช้ข้าวที่เสียหาย ถ้าไม่มีให้ ต้องขายตัวและทรัพย์สินเพื่อนำเงินมาชดใช้','Hammurabi’s law 53 says that if a man neglects his dike and it floods others’ fields, he must replace the grain he destroyed; if he cannot, he and his goods are sold to pay for it.'),
 o:[opt(X('ฟ้องผู้พิพากษาตามกฎหมาย','Take it to the judges under the law'),S=>{fx({f:8,b:-3,p:2});return X('ผู้พิพากษาสั่งให้เพื่อนบ้านชดใช้ข้าวเต็มจำนวน เขาไม่มองหน้าคุณอีกเลย','The judges order your neighbour to repay all the grain. He never looks you in the face again.')}),
    opt(X('ตกลงกันเองให้เขาช่วยทำนาปีหน้า','Settle it: he works your field next year'),S=>{fx({f:4,b:3,so:2});return X('ปีต่อมาเพื่อนบ้านไถนาให้คุณ และซ่อมคันนาของตัวเองด้วย','Next year your neighbour ploughs your field, and mends his own dike too.')}),
    opt(X('ยกโทษให้','Forgive him'),S=>{fx({b:4,f:-2});return X('เขาส่งปลาแห้งมาให้ทุกเดือนจนสิ้นปี','He sends you dried fish every month until the year’s end.')})]},
{id:'a4_gilg_tale',a:[14,60],w:2.5,ch:4,cond:S=>['ed','akk','uruk'].includes(era4(S.ya)),t:X('เรื่องเล่าของกิลกาเมช','Tales of Gilgamesh'),
 x:X('ที่ร้านเบียร์ ชายแก่คนหนึ่งเล่าเรื่องกิลกาเมช ราชาแห่งอูรุกผู้สร้างกำแพงเมือง และเอนคิดู สหายที่เทพสร้างขึ้นจากดินเหนียวในป่า','In the tavern an old man tells of Gilgamesh, the king of Uruk who built its walls, and Enkidu, the friend the gods made from clay in the wild.'),
 n:X('กิลกาเมชอาจเป็นกษัตริย์จริงของอูรุก ราว 2700 ปีก่อนคริสตกาล บทกวีสุเมเรียนเกี่ยวกับเขาถูกเขียนลงแผ่นดินเหนียวราว 2100 ปีก่อนคริสตกาล ส่วนมหากาพย์ฉบับรวมเล่มภาษาอัคคาเดียนมาทีหลังอีกหลายร้อยปี','Gilgamesh may have been a real king of Uruk around 2700 BCE. Sumerian poems about him were written down around 2100 BCE; the full Akkadian epic came centuries later.'),
 o:[opt(X('ฟังจนจบแล้วเล่าต่อให้ลูกหลาน','Listen to the end, and retell it at home'),S=>{S.gilg++;fx({so:3,kn:2});return X('คุณเล่าเรื่องเอนคิดูให้เด็กๆ ฟังจนพวกเขาหลับ','You tell the children about Enkidu until they fall asleep.')}),
    opt(X('ถามว่ากิลกาเมชเป็นคนจริงไหม','Ask if Gilgamesh was real'),S=>{S.gilg++;fx({kn:3});return X('ชายแก่ชี้ไปที่กำแพงเมือง “ก็เขาสร้างมันไว้ไม่ใช่หรือ”','The old man points to the city wall. “Well, who else built that?”')})]},
{id:'a4_siduri',a:[25,70],w:6,ch:4,cond:S=>S.gilg>=2&&!S.sid,t:X('คำแนะนำของซิดูรี','Siduri’s advice'),
 x:X('คุณอ่านถึงตอนที่กิลกาเมชออกตามหาชีวิตอมตะ หญิงเจ้าของร้านเบียร์ชื่อซิดูรีบอกเขาว่า ชีวิตที่ไม่มีวันตายนั้นเทพเก็บไว้กับตัวเอง ส่วนมนุษย์ควรกินให้อิ่ม เต้นรำ อาบน้ำ แต่งตัวสะอาด รักเด็กที่จับมือเรา และให้คนรักมีความสุขในอ้อมกอด','You read the part where Gilgamesh searches for eternal life. A tavern keeper named Siduri tells him the gods kept life without death for themselves; a person should eat well, dance, bathe, wear clean clothes, cherish the child holding their hand, and let their beloved delight in their embrace.'),
 n:X('คำของซิดูรีพบในแผ่นจารึกฉบับบาบิโลนเก่าจากซิปปาร์ ราว 1800 ปีก่อนคริสตกาล ในฉบับมาตรฐานรุ่นหลังข้อความนี้หายไป ในเกมถอดความเป็นคำพูดใหม่','Siduri’s speech survives on an Old Babylonian tablet from Sippar, about 1800 BCE; it was dropped from the later standard version. The game retells it in new words.'),
 o:[opt(X('ใช้ชีวิตตามที่ซิดูรีบอก','Live as Siduri says'),S=>{S.sid='joy';fx({b:8,h:4});return X('คุณเลิกทำงานเร็วขึ้นหนึ่งชั่วโมงทุกวัน เพื่อไปนั่งกับเด็กๆ ริมคลอง','You stop work an hour earlier each day to sit with the children by the canal.')}),
    opt(X('ทำงานที่จะอยู่ไปนานกว่าตัวเอง เหมือนกำแพงอูรุก','Make something that will outlast you, like the walls of Uruk'),S=>{S.sid='fame';fx({p:6,cr:3});return X('คุณตัดสินใจว่าชื่อของคุณจะอยู่ในงานของคุณ','You decide your name will live in your work.')}),
    opt(X('ตามหาความรู้ที่ไม่มีใครรู้','Seek what no one knows'),S=>{S.sid='seek';fx({kn:6,tr:2});return X('คุณเริ่มถามคำถามที่ทำให้นักบวชอึดอัด','You begin asking questions that make the priests uneasy.')})]},
{id:'a4_garden',a:[20,60],w:6,ch:4,cond:S=>era4(S.ya)==='nb'&&S.rg==='bab'&&(S.car==='gardener'||S.car==='builder'||S.car==='scribe'||S.cls!=='slave'),t:X('สวนบนขั้นบันได','Gardens on the terraces'),
 x:X('ข่าวในวังว่าพระราชาจะสร้างสวนบนอาคารขั้นบันไดสูง ปลูกต้นไม้จากภูเขาให้พระราชินีที่คิดถึงบ้านเกิด ปัญหาคือจะยกน้ำขึ้นไปถึงยอดได้อย่างไร','Word in the palace is that the king will raise a garden on high terraces, planting mountain trees for a queen homesick for her hills. The problem is how to lift the water to the top.'),
 n:X('สวนลอยแห่งบาบิโลนเป็นหนึ่งในเจ็ดสิ่งมหัศจรรย์ของโลกยุคโบราณ แต่ไม่มีแผ่นจารึกบาบิโลนแผ่นใดเอ่ยถึงเลย เรื่องสวนลอยมาจากนักเขียนกรีกและโรมันหลายร้อยปีต่อมา เรื่องพระราชินีผู้คิดถึงภูเขาก็มาจากแหล่งเหล่านั้น นักวิชาการสเตฟานี ดัลลีย์เสนอว่าสวนอาจอยู่ที่นีนะเวห์ สร้างโดยพระเจ้าเซนนาเคอริบ นักวิชาการยังถกเถียงกันว่าสวนนี้มีจริงหรือไม่','The Hanging Gardens of Babylon were one of the Seven Wonders of the ancient world, yet no Babylonian tablet mentions them. The story, including the homesick queen, comes from Greek and Roman writers centuries later. The scholar Stephanie Dalley argued the gardens were at Nineveh, built by King Sennacherib. Whether they existed is still debated.'),
 o:[opt(X('ใช้โซ่ถังน้ำวนขึ้นไป หมุนด้วยแรงคน','A loop of buckets on a chain, turned by men'),S=>{S.hg=1;fx({p:6,cr:4,h:-3});ms(X('ช่วยสร้างสวนบนขั้นบันได','Helped build the terrace gardens'));return X('ต้องใช้คนหมุนวงล้อทั้งวันทั้งคืน แต่ปีต่อมาต้นไม้บนยอดก็ผลิใบ','It takes men turning the wheel day and night, but the next year the trees on top break into leaf.')}),
    opt(X('ลองทำเกลียวทองแดงยักษ์หมุนดูดน้ำขึ้นมา','Try a giant spiral of copper that turns and draws water up'),S=>{if(rnd()<.45){S.hg=2;fx({p:10,kn:5});ms(X('คิดเครื่องยกน้ำให้สวนหลวง','Devised a water-lifter for the royal garden'));return X('ช่างหล่อพูดว่าเป็นไปไม่ได้ จนกระทั่งน้ำไหลออกที่ยอดเป็นครั้งแรก','The casters say it cannot be done, until water spills out at the top for the first time.')}fx({b:-3});return X('เกลียวแรกแตกตอนหล่อ ทองแดงหลายตะลันต์เสียไปเปล่าๆ','The first spiral cracks in casting, and talents of copper are wasted.')}),
    opt(X('บอกว่าสวนแบบนี้ไม่คุ้มกับแรงคน','Say such a garden is not worth the labour'),S=>{fx({b:-2,kn:2});return X('ไม่มีใครฟัง งานก่อสร้างเริ่มขึ้นโดยไม่มีคุณ','No one listens; the building starts without you.')})]},
{id:'a4_ishtar',a:[16,60],w:4,ch:4,cond:S=>era4(S.ya)==='nb'&&S.rg==='bab',t:X('อิฐเคลือบสีฟ้า','Blue glazed bricks'),
 x:X('ช่างหลวงต้องการคนช่วยเผาอิฐเคลือบสีฟ้าเข้ม ปั้นเป็นรูปสิงโต วัวป่า และมังกรมุชฮุชชู สำหรับประตูใหม่ของเทพีอิชตาร์','The royal craftsmen need help firing deep blue glazed bricks moulded with lions, wild bulls and mushhushshu dragons, for the new gate of the goddess Ishtar.'),
 n:X('ประตูอิชตาร์สร้างราว 575 ปีก่อนคริสตกาล สมัยพระเจ้าเนบูคัดเนซซาร์ที่ 2 ส่วนที่ขุดได้ถูกนำมาประกอบใหม่ที่พิพิธภัณฑ์เปอร์กามอนในกรุงเบอร์ลิน','The Ishtar Gate was built about 575 BCE under Nebuchadnezzar II. Excavated pieces were rebuilt in the Pergamon Museum in Berlin.'),
 o:[opt(X('ไปช่วยที่เตาเผา','Work at the kilns'),S=>{fx({cr:5,h:-2,p:3});ms(X('ช่วยเผาอิฐให้ประตูอิชตาร์','Fired bricks for the Ishtar Gate'));return X('ทุกครั้งที่เดินผ่านประตู คุณมองหาสิงโตตัวที่คุณช่วยเผา','Every time you pass the gate, you look for the lion you helped fire.')}),
    opt(X('ไปดูขบวนแห่ในวันปีใหม่','Watch the New Year procession'),S=>{fx({b:4});return X('รูปเคารพของมาร์ดุกถูกแห่ผ่านประตูฟ้าคราม ฝูงชนเงียบกริบ','The statue of Marduk is carried through the blue gate; the crowd falls silent.')})]},
{id:'a4_akitu',a:[14,70],w:2,ch:4,cond:S=>['nb'].includes(era4(S.ya))&&S.rg==='bab',t:X('เทศกาลอากีตู','The Akitu festival'),
 x:X('ในวันปีใหม่ คุณเห็นมหาปุโรหิตถอดเครื่องราชของพระราชา แล้วตบหน้าพระองค์ต่อหน้าเทพมาร์ดุก ทุกคนรอดูว่าน้ำตาพระราชาจะไหลไหม','At the New Year festival you see the high priest strip the king of his regalia and strike his face before Marduk. Everyone watches to see whether the king’s tears will flow.'),
 n:X('ในพิธีอากีตูของบาบิโลน มหาปุโรหิตตบหน้ากษัตริย์ ถ้าน้ำตาไหล ถือว่ามาร์ดุกพอใจและปีนั้นจะดี พิธีนี้ทำให้กษัตริย์ต้องยอมรับว่าอำนาจมาจากเทพทุกปี','In Babylon’s Akitu rite the high priest struck the king; if tears came, Marduk was pleased and the year would be good. Each year the king had to accept that his power came from the god.'),
 o:[opt(X('ภาวนาให้น้ำตาไหล','Pray for the tears to come'),S=>{fx({b:3});if(rnd()<.7)return X('น้ำตาไหล ฝูงชนโห่ร้องดีใจ','The tears come, and the crowd roars with joy.');fx({b:-2});return X('ไม่มีน้ำตา ผู้คนกลับบ้านอย่างกังวล','No tears. People go home uneasy.')})]},
{id:'a4_exile',a:[18,60],w:3,ch:4,cond:S=>era4(S.ya)==='nb'&&S.ya<=2620&&S.rg==='bab',t:X('เพื่อนบ้านจากแดนไกล','Neighbours from far away'),
 x:X('ครอบครัวชาวยูดาห์ที่ถูกกวาดต้อนมาย้ายมาอยู่ใกล้บ้านคุณ พวกเขาพูดภาษาอื่น ไหว้พระเจ้าองค์เดียว และไม่ยอมกินของบางอย่าง','A family of Judean captives settles near your house. They speak another tongue, worship one god, and will not eat certain foods.'),
 n:X('ชาวยูดาห์จำนวนมากถูกกวาดต้อนมาบาบิโลเนียหลังปี 597 และ 586 ปีก่อนคริสตกาล บางคนทำงาน ค้าขาย และตั้งรกรากอยู่หลายชั่วคน แผ่นจารึกจากเมืองที่ชื่อว่า “เมืองยูดาห์” บันทึกชีวิตประจำวันของพวกเขา','Many Judeans were deported to Babylonia after 597 and 586 BCE. Some worked, traded and settled for generations; tablets from a town called “Judah-town” record their daily lives.'),
 o:[opt(X('ช่วยพวกเขาหางาน','Help them find work'),S=>{fx({b:5,so:3});const p=mkP('friend',S.age);return PX(p,'ลูกชายของครอบครัวนั้น ชื่อ{p} ได้งานที่คลอง และกลายเป็นเพื่อนสนิทของคุณ','The family’s son, {p}, gets work on the canal and becomes your close friend.')}),
    opt(X('ฟังเพลงของพวกเขา','Listen to their songs'),S=>{fx({kn:3,b:2});return X('เพลงหนึ่งพูดถึงการแขวนพิณไว้บนต้นหลิวริมแม่น้ำ คุณจำทำนองได้ทั้งชีวิต','One song tells of hanging harps on the willows by the river. You remember the tune all your life.')}),
    opt(X('อยู่ห่างๆ ไว้','Keep your distance'),S=>{fx({b:-1});return X('คุณไม่เคยรู้จักพวกเขาจริงๆ','You never really know them.')})]},
{id:'a4_liver',a:[20,65],w:2,ch:4,cond:S=>S.car==='priest'||S.cls==='elite',t:X('อ่านตับแกะ','Reading the liver'),
 x:X('ก่อนพระราชาจะยกทัพ นักบวชผ่าแกะ แล้วเรียกคุณมาช่วยดูรูปร่างของตับ ว่าเทพจะตอบว่าอย่างไร','Before the king marches, the priests slaughter a sheep and call you to help read the shape of its liver for the gods’ answer.'),
 n:X('การทำนายจากตับแกะเป็นวิชาสำคัญของนักบวชบาบิโลน พบหุ่นตับแกะทำด้วยดินเหนียวที่มีคำทำนายเขียนกำกับไว้ แผ่นจารึกคำทำนายหลายพันแผ่นถูกคัดลอกต่อกันมาหลายร้อยปี','Reading sheep’s livers was a central skill of Babylonian priests. Clay models of livers inscribed with omens have been found, and thousands of omen tablets were copied for centuries.'),
 o:[opt(X('อ่านว่าลางดี','Read it as favourable'),S=>{if(rnd()<.6){fx({p:5});return X('กองทัพชนะ ทุกคนบอกว่าตับไม่เคยโกหก','The army wins, and everyone says the liver never lies.')}fx({p:-5});return X('กองทัพแพ้ บางคนเริ่มมองคุณอย่างสงสัย','The army is beaten, and some begin to look at you with doubt.')}),
    opt(X('อ่านว่าลางร้าย ให้รอไปก่อน','Read it as ill: wait'),S=>{fx({kn:3});return X('พระราชารอไปหนึ่งเดือน แล้วสั่งให้ทำนายใหม่','The king waits a month, then orders a new reading.')})]},
{id:'a4_ration',a:[18,60],w:2.5,ch:4,cond:S=>S.cls==='dep'||S.cls==='slave',t:X('ปันส่วนเดือนนี้','This month’s ration'),
 xf:S=>S.sex==='f'?X('เจ้าหน้าที่ตวงข้าวบาร์เลย์ให้ผู้หญิงครึ่งหนึ่งของผู้ชาย ทั้งที่คุณทอผ้าทั้งวันเหมือนพวกเขาทำงาน','The official measures out half as much barley for the women as for the men, though you weave all day just as they work.'):X('เจ้าหน้าที่ตวงข้าวบาร์เลย์ขาดไปหลายถ้วย แล้วบอกว่าปีนี้วิหารก็ขาดแคลน','The official measures your barley several cups short, saying the temple is short this year too.'),
 n:X('บัญชีปันส่วนสมัยราชวงศ์ที่สามแห่งอูร์ระบุว่าคนงานชายได้ข้าวบาร์เลย์ราว 60 ซีลาต่อเดือน คนงานหญิงราว 30 ซีลา เด็กได้น้อยกว่านั้น วิหารและวังมีคนงานทอผ้าหญิงนับพันคน','Ration lists of the Third Dynasty of Ur give male workers about 60 sila of barley a month, women about 30, and children less. Temples and palaces employed thousands of women weavers.'),
 o:[opt(X('รวมกลุ่มกันไปร้องเรียนต่อหัวหน้า','Go with the others to complain to the overseer'),S=>{if(rnd()<.45){fx({f:5,b:4});return X('หัวหน้ายอมเพิ่มให้คนละถ้วย ไม่มาก แต่เป็นชัยชนะ','The overseer adds a cup each. Not much, but a victory.')}fx({b:-3,h:-2});return X('คนที่พูดดังที่สุดถูกตี และคุณไม่ได้อะไรเพิ่ม','The loudest of you is beaten, and you get nothing more.')}),
    opt(X('ก้มหน้ารับไป','Accept it in silence'),S=>{fx({b:-1});return X('คุณแบ่งข้าวให้ลูกก่อนตัวเองเหมือนทุกเดือน','As every month, you feed the children before yourself.')})]},
{id:'a4_freedom',a:[18,60],w:4,ch:4,cond:S=>S.cls==='slave'&&S.ag>=6,t:X('ซื้ออิสรภาพ','Buying freedom'),
 x:X('คุณเก็บเงินที่ได้จากงานพิเศษมาหลายปี จนพอจะไถ่ตัวเองได้ เจ้านายลังเลอยู่นาน','For years you have saved silver from extra work, until you have enough to redeem yourself. Your master hesitates a long time.'),
 n:X('ทาสในเมโสโปเตเมียบางคนมีทรัพย์สิน ทำธุรกิจ และไถ่ตัวเองได้ บางคนได้รับอิสรภาพด้วยการรับเป็นบุตรบุญธรรม สัญญาปลดปล่อยบางฉบับระบุว่า “หน้าผากของเขาสะอาดแล้ว”','Some Mesopotamian slaves held property, did business and could buy their freedom; others were freed by adoption. Some release contracts say “his forehead is cleared”.'),
 o:[opt(X('ยื่นเงินทั้งหมดให้','Offer all of it'),S=>{if(rnd()<.65){S.ag-=6;S.cls='free';fx({b:10,p:4});ms(X('ไถ่ตัวเองจนเป็นอิสระ','Bought your own freedom'));return X('อาลักษณ์เขียนสัญญา “หน้าผากของเขาสะอาดแล้ว” คุณเดินออกไปเป็นคนอิสระ','The scribe writes the contract: “his forehead is cleared.” You walk out a free person.')}fx({b:-5});return X('เจ้านายรับเงินไว้ส่วนหนึ่ง แล้วบอกว่ายังไม่พอ','Your master keeps part of the silver and says it is not yet enough.')})]},
{id:'a4_adopt',a:[30,55],w:3,ch:4,cond:S=>!S.kids.some(k=>k.dies==null),t:X('บุตรบุญธรรม','An adopted child'),
 x:X('คุณไม่มีลูกที่จะดูแลยามแก่ เพื่อนบ้านที่ยากจนมีลูกเจ็ดคน และยินดีให้คุณรับลูกคนหนึ่งเป็นบุตรบุญธรรม','You have no child to care for you in old age. A poor neighbour has seven children and is willing to let you adopt one.'),
 n:X('การรับบุตรบุญธรรมพบบ่อยในเมโสโปเตเมีย มีสัญญาเป็นลายลักษณ์อักษร บุตรบุญธรรมต้องเลี้ยงดูพ่อแม่ยามแก่ และทำพิธีให้หลังจากตาย ส่วนพ่อแม่ต้องให้มรดก','Adoption was common in Mesopotamia and recorded in written contracts: the child had to support the parents in old age and perform their rites after death, and the parents had to leave an inheritance.'),
 o:[wOpt(X('รับเลี้ยง และทำสัญญา','Adopt, with a contract'),S=>{doWrite(S,'contract');S.kids.push({born:S.age,dies:null,adopt:1});fx({b:8});ms(X('รับบุตรบุญธรรม','Adopted a child'));return X('เด็กคนนั้นเรียกคุณว่าแม่หรือพ่อตั้งแต่คืนแรก','The child calls you mother or father from the first night.')}),
    opt(X('ไม่รับ','Decline'),S=>{fx({b:-2});return X('บ้านของคุณยังเงียบเหมือนเดิม','Your house stays as quiet as before.')})]},
{id:'a4_astro',a:[20,70],w:3,ch:4,cond:S=>era4(S.ya)==='nb'&&S.lit>=40&&(S.car==='scribe'||S.car==='priest'||S.focus==='stars'),t:X('บันทึกท้องฟ้า','The diary of the sky'),
 x:X('คืนนี้ดาวพฤหัสบดีเคลื่อนเข้าใกล้ดวงจันทร์ หัวหน้าบอกให้คุณจดทุกอย่างที่เห็น ทั้งดาว ราคาข้าว และระดับน้ำในแม่น้ำ','Tonight Jupiter draws close to the moon. Your master tells you to record everything you see: the stars, the price of barley and the river’s level.'),
 n:X('นักดาราศาสตร์บาบิโลนเขียน “บันทึกประจำวันทางดาราศาสตร์” ต่อเนื่องตั้งแต่ราว 652 ปีก่อนคริสตกาลจนถึงศตวรรษที่ 1 ก่อนคริสตกาล นับเป็นบันทึกทางวิทยาศาสตร์ที่ต่อเนื่องยาวที่สุดในโลกยุคโบราณ พวกเขาทำนายอุปราคาได้จากรอบที่จดไว้','Babylonian astronomers kept “astronomical diaries” from about 652 BCE into the first century BCE, the longest continuous scientific record of the ancient world. From the cycles they recorded, they could predict eclipses.'),
 o:[opt(X('จดทุกคืนไม่ขาด','Record every night without fail'),S=>{S.tabN+=3;S.tabK.sky=(S.tabK.sky||0)+3;fx({kn:6,h:-1});ms(X('จดบันทึกท้องฟ้าให้นักดาราศาสตร์บาบิโลน','Kept the diary of the sky for Babylon’s astronomers'));return X('สองปีต่อมา คุณทำนายจันทรุปราคาได้ถูกต้องเป็นครั้งแรก','Two years later you predict a lunar eclipse correctly for the first time.')}),
    opt(X('สนใจลางบอกเหตุมากกว่าตัวเลข','Care more for the omens than the numbers'),S=>{fx({so:3,p:2});return X('คุณอ่านลางให้คนในวังฟัง พวกเขาชอบลางมากกว่าตัวเลข','You read omens to the palace, which likes them better than numbers.')})]},
{id:'a4_enhed',a:[16,60],w:4,ch:4,cond:S=>era4(S.ya)==='akk'&&S.ya<=4300&&(S.lit>=30||S.car==='priest'),t:X('เพลงสวดของเอนเฮดูอันนา','The hymns of Enheduanna'),
 x:X('คุณได้คัดลอกเพลงสวดถึงเทพีอินันนา ผู้แต่งคือเอนเฮดูอันนา ธิดาของพระเจ้าซาร์กอน และมหาปุโรหิตหญิงของเทพจันทร์ที่อูร์','You are given a hymn to Inanna to copy. Its author is Enheduanna, daughter of King Sargon and high priestess of the moon god at Ur.'),
 n:X('เอนเฮดูอันนา (ราว 2285–2250 ปีก่อนคริสตกาล) มักถูกเรียกว่าผู้ประพันธ์คนแรกของโลกที่รู้จักชื่อ บทเพลงของเธอถูกคัดลอกในโรงเรียนอาลักษณ์อีกหลายร้อยปี แม้นักวิชาการบางคนสงสัยว่าเธอแต่งเองทั้งหมดหรือไม่','Enheduanna (about 2285–2250 BCE) is often called the first author known by name. Her hymns were copied in scribal schools for centuries, though some scholars doubt she wrote all of them.'),
 o:[opt(X('ท่องจนขึ้นใจ','Learn it by heart'),S=>{fx({kn:4,so:2});S.lit+=2;return X('คืนนั้นคุณท่องเพลงสวดในความมืด เสียงของคุณสั่น','That night you recite the hymn in the dark, your voice shaking.')}),
    opt(X('แต่งเพลงสวดของตัวเอง','Write a hymn of your own'),S=>{S.hymn=1;doWrite(S,'hymn');fx({p:4,kn:3});ms(X('แต่งเพลงสวดของตัวเอง','Wrote a hymn of your own'));return X('คุณซ่อนแผ่นจารึกนั้นไว้ใต้เตียง ไม่กล้าให้ใครดู','You hide the tablet under your bed and dare not show anyone.')})]},
{id:'a4_dilmun',a:[20,55],w:1.5,ch:4,cond:S=>S.car==='merchant'||(S.ag>=10&&S.cls!=='slave'),t:X('เรือไปดิลมุน','A ship to Dilmun'),
 x:X('เรือบรรทุกผ้าขนแกะและน้ำมันกำลังจะล่องลงอ่าวไปดิลมุน แล้วต่อไปมากัน เพื่อแลกทองแดง พ่อค้าชวนคุณร่วมลงทุน','A ship loaded with wool and oil is about to sail down the Gulf to Dilmun, and on to Magan, to trade for copper. The merchants invite you to invest.'),
 n:X('ดิลมุน (บาห์เรนวันนี้) เป็นท่าค้าขายสำคัญ ทองแดงมาจากมากัน (โอมานวันนี้) และสินค้าบางอย่างมาจากเมลูฮา หรือลุ่มแม่น้ำสินธุ ตราประทับแบบสินธุพบที่อูร์ แสดงว่าสองอารยธรรมนี้ติดต่อกันทางทะเล','Dilmun (today’s Bahrain) was a key trading port. Copper came from Magan (today’s Oman), and some goods came from Meluhha, the Indus Valley; Indus-style seals found at Ur show the two civilisations were linked by sea.'),
 o:[opt(X('ร่วมลงทุน','Invest'),S=>{S.ag-=3;if(rnd()<.65){S.ag+=8;fx({p:3});return X('เรือกลับมาพร้อมทองแดงเต็มลำ เงินของคุณงอกเป็นเกือบสามเท่า','The ship returns full of copper, and your silver nearly triples.')}fx({b:-4});return X('เรือไม่กลับมา ไม่มีใครรู้ว่าเกิดอะไรขึ้น','The ship never returns, and no one learns why.')}),
    opt(X('ล่องเรือไปเอง','Sail with it yourself'),S=>{S.yr+=.03;if(rnd()<.7){S.ag+=6;fx({tr:6,kn:3});ms(X('ล่องเรือไปค้าขายถึงดิลมุน','Sailed to Dilmun to trade'));return X('คุณเห็นทะเลเป็นครั้งแรก และคนจากเมลูฮาที่พูดภาษาที่ไม่มีใครเข้าใจ','You see the open sea for the first time, and people from Meluhha speaking a language no one understands.')}fx({h:-12});return X('พายุในอ่าวเกือบพาเรือจม คุณกลับมาด้วยไข้และมือเปล่า','A storm in the Gulf nearly sinks the ship. You come home feverish and empty-handed.')}),
    opt(X('ไม่เสี่ยง','Do not risk it'),S=>X('คุณอยู่บ้าน เงินของคุณก็อยู่ที่เดิม','You stay home, and so does your silver.'))]},
{id:'a4_salt',a:[20,60],w:2,ch:4,cond:S=>S.field&&['ur','lag','uru'].includes(S.rg)&&['ur3','ob'].includes(era4(S.ya)),t:X('ดินขาวเพราะเกลือ','Fields turning white'),
 x:X('ในนาของคุณมีคราบขาวขึ้นเป็นหย่อมๆ ข้าวสาลีขึ้นได้น้อยลงทุกปี ผู้เฒ่าบอกว่าดินกำลังเค็ม','White patches crust your field, and the wheat comes up thinner every year. The elders say the soil is turning salty.'),
 n:X('การทดน้ำต่อเนื่องหลายร้อยปีทำให้เกลือสะสมในดินทางใต้ของเมโสโปเตเมีย นักวิชาการบางคนเสนอว่าชาวนาจึงหันไปปลูกข้าวบาร์เลย์ที่ทนเค็มกว่าแทนข้าวสาลี แต่ว่าเกลือมีผลต่อการเสื่อมของเมืองทางใต้มากแค่ไหนยังถกเถียงกัน','Centuries of irrigation built up salt in the soils of southern Mesopotamia. Some scholars argue farmers shifted from wheat to the more salt-tolerant barley, but how much salt caused the decline of the southern cities is debated.'),
 o:[opt(X('เลิกปลูกข้าวสาลี หันไปปลูกข้าวบาร์เลย์','Give up wheat for barley'),S=>{fx({f:3,kn:3});return X('ข้าวบาร์เลย์ขึ้นดีกว่า แต่ราคาต่ำกว่า','The barley does better, though it fetches less.')}),
    opt(X('ปล่อยนาให้พักหนึ่งปี','Let the field lie fallow a year'),S=>{fx({f:-4,kn:4});return X('ปีต่อมาดินดีขึ้นเล็กน้อย','The next year the soil is a little better.')})]},
{id:'a4_kubaba',a:[25,60],w:8,ch:4,lg:1,cond:S=>S.leg&&S.sex==='f'&&S.car==='brewer'&&S.clv>=2&&era4(S.ya)==='ed'&&S.rg==='kis'&&!S.kingT,t:X('จากร้านเบียร์สู่บัลลังก์','From the tavern to the throne'),
 x:X('เมืองคีชไร้กษัตริย์ ผู้คนที่เคยดื่มเบียร์ในร้านของคุณมาหลายสิบปีมายืนเต็มหน้าร้าน และเรียกร้องให้คุณปกครองเมือง','Kish has no king. People who have drunk in your tavern for decades crowd the door and call on you to rule the city.'),
 n:X('บัญชีรายพระนามกษัตริย์สุเมเรียนระบุว่ากูบาบา “หญิงเจ้าของร้านเบียร์” เป็นกษัตริย์แห่งคีชและครองราชย์ 100 ปี เธอเป็นผู้หญิงคนเดียวในบัญชีที่ครองราชย์ด้วยสิทธิของตัวเอง แต่บัญชีนี้ผสมตำนานกับประวัติศาสตร์ จึงไม่รู้ว่าเธอมีตัวตนจริงหรือไม่','The Sumerian King List says Kubaba, “the woman tavern keeper”, became king of Kish and reigned 100 years. She is the only woman in the list to rule in her own right, but the list mixes legend and history, so no one knows if she was real.'),
 o:[opt(X('รับตำแหน่ง ✦','Take the throne ✦'),S=>{S.kingT=X('ผู้ครองคีช ผู้เคยเป็นเจ้าของร้านเบียร์ ✦','ruler of Kish, once a tavern keeper ✦');fx({p:30,b:10});ms(X('ขึ้นครองคีช ✦','Became ruler of Kish ✦'));return X('คุณปกครองคีชด้วยความรู้เดียวที่มี: ทุกคนต้องได้กินและดื่มอย่างยุติธรรม','You rule Kish with the one thing you know: everyone must eat and drink fairly.')}),
    opt(X('ปฏิเสธ แล้วกลับไปหมักเบียร์','Refuse, and go back to brewing'),S=>{fx({b:4});return X('ทุกคนผิดหวัง แต่เบียร์ของคุณยังดีที่สุดในคีช','Everyone is disappointed, but your beer is still the best in Kish.')})]},
{id:'a4_sargon',a:[22,50],w:8,ch:4,lg:1,cond:S=>S.leg&&S.sex==='m'&&(S.car==='gardener'||S.car==='soldier')&&S.clv>=2&&S.ya<=4370&&S.ya>=4330&&!S.kingT,t:X('ความฝันของถ้วยเครื่องดื่ม','The cupbearer’s dream'),
 x:X('คุณได้เป็นคนถือถ้วยเครื่องดื่มของพระราชาแห่งคีช คืนหนึ่งคุณฝันว่าเทพีอินันนาจมพระราชาลงในแม่น้ำเลือด พระราชาหวาดกลัว และส่งคุณไปเมืองอื่นพร้อมแผ่นจารึกที่ปิดผนึก','You have become the king of Kish’s cupbearer. One night you dream that Inanna drowns the king in a river of blood. Afraid, the king sends you to another city with a sealed tablet.'),
 n:X('ตำนานเล่าว่าซาร์กอนเกิดจากนักบวชหญิง ถูกใส่ตะกร้ากกลอยแม่น้ำ คนตักน้ำชื่ออักกีเก็บไปเลี้ยงเป็นคนสวน แล้วได้เป็นคนถือถ้วยของพระเจ้าอูร์-ซาบาบาแห่งคีช ก่อนจะยึดอำนาจ ตำนานในเกมดัดแปลงจากเรื่องเหล่านี้ ซึ่งเขียนขึ้นหลังสมัยซาร์กอนหลายร้อยปี','Legend says Sargon was born to a priestess and set adrift in a reed basket, raised by a water-drawer named Aqqi as a gardener, and became cupbearer to King Ur-Zababa of Kish before seizing power. The game adapts these tales, which were written centuries after Sargon.'),
 o:[opt(X('ทุบแผ่นจารึกดูว่าเขียนอะไรไว้ ✦','Break the tablet to see what it says ✦'),S=>{S.kingT=X('ผู้ตั้งราชวงศ์ใหม่ ✦','founder of a new dynasty ✦');fx({p:30});S.yr+=.02;ms(X('ยึดอำนาจและตั้งราชวงศ์ใหม่ ✦','Seized power and founded a dynasty ✦'));return X('แผ่นจารึกสั่งให้ฆ่าผู้ถือสาร คุณหันหลังกลับ รวบรวมคนสวนและทหาร แล้วเดินเข้าคีชในฐานะพระราชาองค์ใหม่','The tablet orders the bearer’s death. You turn back, gather gardeners and soldiers, and march into Kish as its new king.')}),
    opt(X('ส่งสารตามคำสั่ง','Deliver it as ordered'),S=>{fx({h:-6,b:-2});return X('คุณรอดมาได้อย่างหวุดหวิด และไม่กลับไปคีชอีกเลย','You escape with your life, barely, and never return to Kish.')})]},
{id:'a4_heal',a:[20,70],w:2,ch:4,cond:S=>!!S.sick||S.h<50,t:X('หมอยาหรือหมอผี','Physician or exorcist'),
 x:X('คุณป่วยมาหลายวัน ครอบครัวถกเถียงว่าจะตามอาซู หมอผู้ใช้สมุนไพรและผ้าพันแผล หรืออาชิปู ผู้ขับผีที่เชื่อว่าโรคมาจากปีศาจ','You have been ill for days. The family argues whether to call an asu, who heals with herbs and bandages, or an ashipu, who drives out the demons believed to cause disease.'),
 n:X('ชาวเมโสโปเตเมียมีผู้รักษาสองแบบ อาซูใช้ยาจากพืช แร่ และผ้าพันแผล อาชิปูใช้คาถาและพิธี บ่อยครั้งสองแบบทำงานร่วมกัน ตำราการแพทย์บนแผ่นดินเหนียวบรรยายอาการอย่างละเอียด','Mesopotamians had two kinds of healer: the asu used medicines from plants and minerals and bandages; the ashipu used incantations and rites. Often they worked together. Medical tablets describe symptoms in detail.'),
 o:[opt(X('ตามอาซู','Call the asu'),S=>{if(S.ag>=1)S.ag--;fx({h:10});return X('ยาพอกขมจนคุณสะดุ้ง แต่แผลเริ่มหาย','The poultice stings bitterly, but the sore begins to heal.')}),
    opt(X('ตามอาชิปู','Call the ashipu'),S=>{if(S.ag>=1)S.ag--;fx({h:5,b:5});return X('อาชิปูท่องคาถาทั้งคืน ครอบครัวรู้สึกสบายใจขึ้นมาก','The ashipu chants all night, and the family feels much better.')}),
    opt(X('ตามทั้งสองคน','Call both'),S=>{S.ag=Math.max(0,S.ag-2);fx({h:10,b:4});return X('ทั้งสองคนทำงานไปพร้อมกันโดยไม่มองหน้ากัน','They work side by side without looking at each other.')})]},
/* ----- elder ----- */
{id:'e4_kispum',deck:'elder',w:4,ch:4,t:X('พิธีเรียกชื่อบรรพบุรุษ','Calling the ancestors’ names'),
 x:X('ทุกเดือน ครอบครัวเทน้ำลงท่อดินเผาที่ฝังลงไปใต้พื้นบ้าน และเรียกชื่อบรรพบุรุษทีละคน ปีนี้คุณเป็นคนเรียก','Each month the family pours water down a clay pipe set into the floor and calls the ancestors by name, one by one. This year you are the one who calls.'),
 n:X('พิธีคิสปุมของชาวเมโสโปเตเมียคือการให้อาหาร น้ำ และเรียกชื่อผู้ตาย เชื่อกันว่าวิญญาณที่ไม่มีใครเรียกชื่อและไม่มีใครเซ่นไหว้จะหิวโหยและเร่ร่อน ชื่อจึงเป็นสิ่งสำคัญมาก','In the Mesopotamian kispum rite the living gave food and water to the dead and called their names. A spirit no one named or fed was believed to wander hungry, so names mattered greatly.'),
 o:[opt(X('สอนหลานให้จำชื่อทุกคน','Teach the grandchildren every name'),S=>{S.kisp=1;fx({b:6,so:2});return X('หลานคนเล็กท่องชื่อได้ครบเจ็ดรุ่น รวมทั้งชื่อของคุณ','The youngest grandchild recites seven generations of names, including yours.')}),
    opt(X('เพิ่มชื่อของคนที่ไม่มีใครเรียก','Add the names of those no one calls'),S=>{S.kisp=1;fx({b:4,p:3});return X('คุณเรียกชื่อเพื่อนเก่าที่ไม่มีลูกหลาน ครอบครัวไม่เข้าใจ แต่ทำตาม','You call the names of old friends who left no children. The family does not understand, but follows you.')})]},
{id:'e4_archive',deck:'elder',w:4,ch:4,cond:S=>S.tabN>=3,t:X('แผ่นจารึกของคุณ','Your tablets'),
 xf:S=>X('คุณเก็บแผ่นดินเหนียวที่เขียนมาทั้งชีวิตไว้ราว '+S.tabN+' แผ่น จะทำอย่างไรกับมันดี','You have kept some '+S.tabN+' tablets you wrote over a lifetime. What will you do with them?'),
 n:X('แผ่นดินเหนียวที่ไม่ได้เผาจะละลายเมื่อเปียก แต่แผ่นที่ถูกเผา ไม่ว่าตั้งใจหรือจากไฟไหม้เมือง อยู่ได้หลายพันปี หอสมุดของพระเจ้าอัสซูร์บานิปาลที่นีนะเวห์รอดมาเพราะเมืองถูกเผาในปี 612 ปีก่อนคริสตกาล นักโบราณคดียังพบจดหมายส่วนตัวเก็บอยู่ในโถใต้พื้นบ้าน','Unbaked clay dissolves when wet, but tablets that were fired, on purpose or when a city burned, last for thousands of years. Ashurbanipal’s library at Nineveh survived because the city was burned in 612 BCE. Archaeologists also find private letters kept in jars beneath house floors.'),
 o:[opt(X('เผาให้แข็ง แล้วเก็บในโถใต้พื้นบ้าน','Bake them hard and store them in a jar under the floor'),S=>{S.bake=2;fx({kn:2});return X('คุณใส่แผ่นจารึกลงในโถทีละแผ่น เหมือนฝังความทรงจำ','You lay the tablets in the jar one by one, as if burying memories.')}),
    opt(X('มอบให้ห้องเก็บแผ่นจารึกของวิหาร','Give them to the temple’s tablet room'),S=>{S.bake=1;fx({p:3});return X('นักบวชรับไว้ และให้อาลักษณ์หนุ่มคัดลอกบางแผ่น','The priests accept them, and have a young scribe copy some.')}),
    opt(X('ขยำกลับเป็นดิน ให้ลูกหลานใช้เขียนต่อ','Knead them back into clay for the grandchildren to write on'),S=>{S.bake=0;S.tabN=Math.ceil(S.tabN/4);fx({b:3});return X('หลานเขียนเครื่องหมายแรกลงบนดินเหนียวที่เคยเป็นงานของคุณ','Your grandchild writes a first sign on clay that was once your work.')})]},
{id:'e4_will',deck:'elder',w:3,ch:4,cond:S=>S.kids.filter(k=>k.dies==null).length>=2,t:X('แบ่งมรดก','Dividing the estate'),
 x:X('ลูกๆ เริ่มถามว่าใครจะได้บ้าน นา และฝูงสัตว์ ลูกคนโตบอกว่าตามธรรมเนียมเขาควรได้มากกว่า','Your children have begun asking who will get the house, the fields and the flock. The eldest says custom gives him more.'),
 n:X('ในยุคบาบิโลนเก่า ลูกชายแบ่งมรดกกัน ลูกคนโตมักได้ส่วนเพิ่ม ลูกสาวได้สินเดิมตอนแต่งงาน มีแผ่นจารึกแบ่งมรดกหลายพันแผ่น บางครอบครัวทะเลาะกันข้ามรุ่น','In the Old Babylonian period sons shared the estate, with the eldest often taking an extra share; daughters received dowries when they married. Thousands of inheritance tablets survive, and some families quarrelled across generations.'),
 o:[wOpt(X('เขียนพินัยกรรมให้ชัด แบ่งเท่ากัน','Write a clear will, sharing equally'),S=>{doWrite(S,'contract');fx({b:4});return X('ลูกคนโตไม่พอใจ แต่ไม่มีใครต้องไปศาล','The eldest is unhappy, but no one goes to court.')}),
    opt(X('ให้ลูกคนโตมากกว่าตามธรรมเนียม','Give the eldest more, by custom'),S=>{fx({b:-2});return X('ลูกคนเล็กเงียบไปหลายวัน','Your youngest is silent for days.')}),
    opt(X('ปล่อยให้ลูกๆ ตกลงกันเอง','Let them settle it among themselves'),S=>{fx({b:-4});return X('หลังคุณจากไป พวกเขาจ้างอาลักษณ์เขียนแผ่นแบ่งมรดกสามครั้ง','After you are gone, they hire a scribe to divide the estate three times over.')})]},
{id:'e4_wall',deck:'elder',w:3,ch:4,cond:S=>S.gilg>=2,t:X('กำแพงอูรุก','The wall of Uruk'),
 x:X('ตอนจบของมหากาพย์ กิลกาเมชกลับบ้านโดยไม่ได้ชีวิตอมตะ เขาชวนคนเรือขึ้นไปเดินบนกำแพงอูรุก ให้ดูอิฐที่เผาไว้อย่างดี สวน และบ่อดินเหนียว คุณอ่านตอนนี้ซ้ำหลายรอบ','At the end of the epic, Gilgamesh comes home without eternal life. He invites the boatman to walk the wall of Uruk and look at its fired bricks, its gardens and its clay pits. You read the passage many times.'),
 n:X('มหากาพย์จบที่ภาพเดียวกับที่ขึ้นต้น คือกำแพงเมืองอูรุก หลายคนอ่านว่ามนุษย์ไม่ได้อยู่ตลอดไป แต่สิ่งที่สร้างไว้และเรื่องที่เล่าต่ออยู่ได้นานกว่า','The epic ends with the same image it began with, the walls of Uruk. Many readers take it to mean that people do not live forever, but what they build and the stories told about them last longer.'),
 o:[opt(X('ขึ้นไปเดินบนกำแพงเมืองของคุณเอง','Walk the wall of your own city'),S=>{fx({b:5,h:1});return X('จากบนกำแพง คุณเห็นหลังคาบ้าน คลอง และทุ่งข้าวที่คนรุ่นคุณทำไว้','From the wall you see the roofs, the canals and the fields your generation made.')}),
    opt(X('เขียนเรื่องชีวิตตัวเองลงแผ่นดินเหนียว','Write the story of your own life in clay'),S=>{doWrite(S,'hymn');S.memoir=1;fx({kn:3,p:3});return X('คุณเขียนได้แค่สามแผ่น แต่ใส่ชื่อของทุกคนที่คุณรักไว้ครบ','You manage only three tablets, but every name you loved is in them.')})]},
];
/* ---------- chapter 04 career decisions ---------- */
const DEC_CAR4=[
{id:'k4_kushim',a:[16,60],w:5,ch:4,cond:S=>S.car==='scribe'&&era4(S.ya)==='uruk',t:X('บัญชีข้าวของโรงเบียร์','The brewery’s barley account'),
 x:X('หัวหน้าโรงเบียร์ของวิหารให้คุณบันทึกข้าวบาร์เลย์ที่รับมาตลอด 37 เดือน คุณกดตัวเลขลงดินเหนียว แล้วลงชื่อผู้รับผิดชอบไว้ท้ายแผ่น','The head of the temple brewery has you record the barley received over 37 months. You press the numbers into clay and add the responsible official’s name at the bottom.'),
 n:X('แผ่นจารึกยุคอูรุกแผ่นหนึ่ง ราว 3100 ปีก่อนคริสตกาล บันทึกข้าวบาร์เลย์ราว 29,086 หน่วยตลอด 37 เดือน และลงท้ายด้วยคำว่า “คูชิม” นักวิชาการบางคนเสนอว่านี่อาจเป็นชื่อคนที่เก่าแก่ที่สุดที่เขียนไว้ แต่คำนี้อาจเป็นตำแหน่งแทนชื่อก็ได้ ตัวอักษรยุคแรกส่วนใหญ่ใช้ทำบัญชี ไม่ใช่เล่าเรื่อง','A Uruk-period tablet of about 3100 BCE records some 29,086 measures of barley over 37 months and ends with the word “Kushim”. Some scholars suggest it may be the oldest written name of a person, though it may be a title instead. Most early writing was accounting, not storytelling.'),
 o:[opt(X('จดตัวเลขอย่างละเอียด','Record the numbers exactly'),S=>{S.tabN+=2;S.tabK.receipt=(S.tabK.receipt||0)+2;fx({kn:4,p:3});return X('หัวหน้าตรวจแล้วไม่พบที่ผิดสักตัว','The overseer checks it and finds not a single error.')}),
    opt(X('ใส่ชื่อของคุณเองไว้มุมแผ่นด้วย','Slip your own name into the corner too'),S=>{S.tabN++;S.nameTab=1;fx({p:2});ms(X('เขียนชื่อตัวเองลงในบัญชีของวิหาร','Wrote your own name into a temple account'));return X('ชื่อของคุณจะอยู่ตรงนั้นนานกว่าที่คุณคิด','Your name will stay there longer than you imagine.')})]},
{id:'k4_mistake',a:[14,60],w:3,ch:4,cond:S=>S.car==='scribe',t:X('เขียนผิดบนดินเปียก','A mistake in wet clay'),
 x:X('คุณเขียนบัญชีแกะผิดไปหนึ่งตัวเลข ดินยังเปียกอยู่','You have written one number wrong in the sheep account, and the clay is still wet.'),
 n:X('อาลักษณ์แก้ข้อความบนดินเหนียวเปียกได้ด้วยการลูบให้เรียบแล้วเขียนใหม่ เมื่อดินแห้งหรือถูกเผาแล้วจะแก้ไม่ได้ เพราะเหตุนี้สัญญาสำคัญจึงถูกเผาให้แข็ง','Scribes could fix wet clay by smoothing it and writing again; once the clay dried or was fired, nothing could be changed. That is why important contracts were baked hard.'),
 o:[opt(X('ลูบแล้วเขียนใหม่','Smooth it and rewrite'),S=>{fx({kn:2});return X('รอยนิ้วโป้งของคุณยังติดอยู่ที่มุมแผ่น','Your thumbprint stays in the corner of the tablet.')}),
    opt(X('ปล่อยไว้ ไม่มีใครเห็นหรอก','Leave it; no one will notice'),S=>{if(rnd()<.4){fx({p:-4});return X('ผู้ตรวจบัญชีเห็น และเรียกคุณไปพบ','The auditor notices and summons you.')}return X('ไม่มีใครเห็นจริงๆ แกะหนึ่งตัวหายไปจากประวัติศาสตร์','No one notices. One sheep vanishes from history.')})]},
{id:'k4_lexical',a:[16,60],w:3,ch:4,cond:S=>S.car==='scribe'&&['ob','nb','ur3'].includes(era4(S.ya)),t:X('พจนานุกรมสองภาษา','A two-language word list'),
 x:X('ภาษาสุเมเรียนไม่มีใครพูดกันที่บ้านแล้ว แต่ยังใช้ในวิหารและวรรณกรรม หัวหน้าให้คุณทำรายการคำภาษาสุเมเรียนคู่กับภาษาอัคคาเดียน','No one speaks Sumerian at home any more, but it lives on in temples and literature. Your master has you make a list of Sumerian words beside their Akkadian meanings.'),
 n:X('ภาษาสุเมเรียนเลิกพูดในชีวิตประจำวันราว 2000–1800 ปีก่อนคริสตกาล แต่ยังใช้ในพิธีและการศึกษาอีกเกือบสองพันปี คล้ายภาษาละตินในยุโรป รายการคำสองภาษาเหล่านี้ช่วยนักวิชาการยุคใหม่อ่านภาษาสุเมเรียนได้','Sumerian stopped being spoken in daily life around 2000–1800 BCE but was used in ritual and learning for nearly two thousand years more, much like Latin in Europe. These bilingual lists later helped modern scholars read Sumerian.'),
 o:[opt(X('ทำรายการให้ครบทุกคำที่รู้','List every word you know'),S=>{S.tabN+=3;S.tabK.list=(S.tabK.list||0)+3;fx({kn:6,p:2});return X('รายการของคุณยาวกว่าเจ็ดแผ่น','Your list runs to more than seven tablets.')}),
    opt(X('ใส่คำหยาบที่นักเรียนชอบใช้ลงไปด้วย','Add the rude words the pupils like to use'),S=>{S.tabN++;fx({b:4,kn:2});return X('หัวหน้าขำจนไอ แล้วลบทิ้งครึ่งหนึ่ง','Your master laughs until he coughs, then rubs half of them out.')})]},
{id:'k4_royal',a:[25,65],w:4,ch:4,cond:S=>S.car==='scribe'&&S.clv>=2,t:X('จารึกชัยชนะของพระราชา','The king’s victory inscription'),
 x:X('พระราชาให้คุณเขียนจารึกชัยชนะครั้งล่าสุด คุณรู้ว่ากองทัพแค่ตีหมู่บ้านเล็กๆ ได้ แต่พระราชาอยากให้เขียนว่าทำลายเมืองใหญ่ห้าเมือง','The king wants an inscription of his latest victory. You know the army took a few small villages, but the king wants it to say five great cities fell.'),
 n:X('จารึกของกษัตริย์เมโสโปเตเมียมักโอ้อวดเกินจริง นักประวัติศาสตร์จึงต้องเทียบกับบัญชี จดหมาย และหลักฐานจากฝ่ายตรงข้าม','Mesopotamian royal inscriptions often exaggerate, so historians compare them with accounts, letters and evidence from the other side.'),
 o:[opt(X('เขียนตามที่พระราชาต้องการ','Write what the king wants'),S=>{S.tabN++;fx({p:5,b:-2});return X('พระราชาพอใจ อีกสี่พันปีต่อมา นักประวัติศาสตร์จะสงสัยตัวเลขของคุณ','The king is pleased. Four thousand years later, historians will doubt your numbers.')}),
    opt(X('เขียนความจริงไว้ในบัญชีอีกแผ่นที่ไม่มีใครอ่าน','Record the truth on a dull account tablet no one reads'),S=>{S.tabN+=2;S.truth=1;fx({kn:4,p:2});return X('จารึกบนศิลาโอ้อวด แต่แผ่นบัญชีของคุณบอกจำนวนแกะที่ยึดได้จริง','The stone boasts; your account tablet records how many sheep were really taken.')})]},
{id:'k4_sour',a:[14,60],w:3,ch:4,cond:S=>S.car==='brewer',t:X('เบียร์เปรี้ยว','The beer turns sour'),
 x:X('อากาศร้อนจัด เบียร์ทั้งโถเปรี้ยวก่อนจะได้ขาย ลูกค้าประจำรออยู่หน้าร้าน','The heat is fierce, and a whole jar turns sour before it can be sold. Regulars wait at the door.'),
 n:X('ชาวเมโสโปเตเมียมีเบียร์หลายชนิด ทั้งเบียร์ดำ เบียร์แดง และเบียร์หวาน รายการคำศัพท์มีชื่อเบียร์กว่ายี่สิบแบบ เบียร์ไม่มีฮอปส์จึงเสียเร็ว ต้องดื่มภายในไม่กี่วัน','Mesopotamians made many beers, dark, red and sweet; word lists name more than twenty kinds. Without hops, beer spoiled quickly and had to be drunk within days.'),
 o:[opt(X('เทอินทผลัมลงไปให้หวานกลบ','Add dates to sweeten it'),S=>{fx({cr:4,b:2});return X('ลูกค้าบอกว่ารสแปลกแต่อร่อย บางคนสั่งแบบนี้อีก','Customers say it tastes odd but good; some order it again.')}),
    opt(X('ทิ้ง แล้วบอกลูกค้าตรงๆ','Pour it out and tell them honestly'),S=>{fx({p:3,f:-2});return X('ลูกค้าเชื่อใจร้านคุณมากขึ้น','Your customers trust your tavern more.')}),
    opt(X('ขายราคาเต็มเหมือนเดิม','Sell it at full price anyway'),S=>{S.ag+=1;fx({p:-4});return X('ได้เงิน แต่คนในย่านเริ่มพูดถึงเบียร์ของคุณในทางไม่ดี','You make the silver, but the quarter starts talking about your beer.')})]},
{id:'k4_measure',a:[18,60],w:3,ch:4,cond:S=>S.car==='brewer'&&S.clv>=1&&['ob','nb'].includes(era4(S.ya)),t:X('ตวงให้ขาด','Short measures'),
 x:X('เจ้าของร้านอีกร้านบอกเคล็ดลับ: ตวงเบียร์ให้ขาดนิดหน่อย แล้วรับข้าวจากลูกค้าด้วยถังที่ใหญ่กว่าปกติ','Another tavern keeper shares a trick: pour the beer a little short, and take payment in grain with an oversized measure.'),
 n:X('กฎหมายฮัมมูราบีข้อ 108 กำหนดว่า ถ้าเจ้าของร้านเบียร์รับข้าวด้วยตาชั่งที่ใหญ่เกิน หรือให้เบียร์น้อยกว่าราคาข้าว ให้นำตัวไปโยนลงน้ำ','Hammurabi’s law 108 says that if a tavern keeper takes grain by an oversized weight, or gives less beer than the grain’s worth, she shall be thrown into the water.'),
 o:[opt(X('ไม่ทำ','Refuse'),S=>{fx({p:2});return X('ร้านของคุณได้กำไรน้อยกว่า แต่นอนหลับสบาย','Your tavern makes less, but you sleep well.')}),
    opt(X('ลองทำดูสักเดือน','Try it for a month'),S=>{S.ag+=2;if(rnd()<.3){fx({h:-20,p:-10});S.yr+=.08;return X('ลูกค้าคนหนึ่งร้องเรียน คุณถูกนำตัวไปที่แม่น้ำ และรอดมาได้อย่างหวุดหวิด','A customer complains. You are taken to the river and barely survive.')}return X('ไม่มีใครรู้ แต่คุณสะดุ้งทุกครั้งที่มีคนมองถังตวง','No one finds out, but you flinch whenever someone eyes the measure.')})]},
{id:'k4_plough',a:[16,60],w:3,ch:4,cond:S=>S.car==='farmer',t:X('คันไถหว่านเมล็ด','The seeder plough'),
 x:X('หัวหน้าทีมไถให้คุณลองคันไถแบบใหม่ ที่มีกรวยหยอดเมล็ดลงร่องไปพร้อมกับไถ','The plough-team leader has you try a new plough with a funnel that drops seed into the furrow as it goes.'),
 n:X('ชาวเมโสโปเตเมียใช้คันไถที่มีกรวยหยอดเมล็ดตั้งแต่ราว 2000 ปีก่อนคริสตกาล หรือก่อนนั้น ช่วยประหยัดเมล็ดพันธุ์ ข้อความ “คำสอนของชาวนา” บรรยายวิธีทำนาทีละขั้นตลอดปี','Mesopotamians used seeder ploughs with a funnel from around 2000 BCE or earlier, saving seed. A text called the Farmer’s Instructions describes a year of farm work step by step.'),
 o:[opt(X('ฝึกจนคล่อง','Practise until it is second nature'),S=>{S.field=Math.min(3,(S.field||1)+1);fx({kn:4,f:4});return X('ร่องของคุณตรงที่สุดในทีม และใช้เมล็ดน้อยลงครึ่งหนึ่ง','Your furrows are the straightest in the team, and use half the seed.')}),
    opt(X('ยังชอบหว่านด้วยมือแบบเดิม','Stick to sowing by hand'),S=>{fx({b:1});return X('หัวหน้าส่ายหน้า แต่ข้าวของคุณก็ยังขึ้น','The leader shakes his head, but your barley still grows.')})]},
{id:'k4_count',a:[16,60],w:3,ch:4,cond:S=>S.car==='herder',t:X('วันนับแกะของวิหาร','The temple’s sheep count'),
 x:X('ถึงวันที่ต้องพาฝูงแกะของวิหารไปให้อาลักษณ์นับ ตามสัญญาคุณต้องส่งลูกแกะและขนแกะให้ครบตามจำนวน แต่ปีนี้หมาป่าคาบไปหลายตัว','The day comes to bring the temple’s flock to the scribes for counting. By contract you owe a set number of lambs and fleeces, but wolves took several this year.'),
 n:X('คนเลี้ยงแกะของวิหารทำสัญญาที่กำหนดจำนวนลูกแกะและขนแกะที่ต้องส่ง ถ้าสัตว์ตายเพราะความประมาทต้องชดใช้ กฎหมายฮัมมูราบีข้อ 266 ยกเว้นให้ ถ้าสัตว์ถูกสัตว์ป่าคาบไปหรือป่วยตายโดยไม่ใช่ความผิดของคนเลี้ยง','Temple shepherds worked under contracts fixing how many lambs and fleeces they owed, and paid for losses caused by neglect. Hammurabi’s law 266 excused the shepherd if a beast was taken by a lion or died of disease through no fault of his.'),
 o:[opt(X('สาบานต่อหน้าเทพว่าเป็นสัตว์ป่า','Swear before the god it was wild beasts'),S=>{fx({b:2});return X('อาลักษณ์จดคำสาบานของคุณ แล้วตัดยอดค้างออก','The scribe records your oath and strikes the shortfall.')}),
    opt(X('ชดใช้ด้วยแกะของตัวเอง','Make it up with your own sheep'),S=>{if(S.herd.sheep>=2)S.herd.sheep-=2;fx({p:3});return X('ฝูงของคุณเล็กลง แต่ชื่อของคุณในบัญชีวิหารสะอาด','Your own flock shrinks, but your name in the temple books is clean.')})]},
{id:'k4_tin',a:[16,60],w:3,ch:4,cond:S=>S.car==='smith',t:X('ดีบุกจากแดนไกล','Tin from far away'),
 x:X('ทองแดงมีพอ แต่ดีบุกหมด กองคาราวานที่นำดีบุกมาจากภูเขาไกลทางตะวันออกยังไม่มา','There is copper enough, but the tin has run out, and the caravan that brings it from mountains far to the east has not come.'),
 n:X('สำริดคือทองแดงผสมดีบุกราวหนึ่งในสิบ แข็งกว่าทองแดงล้วน เมโสโปเตเมียไม่มีทั้งทองแดงและดีบุก ต้องนำเข้า ดีบุกอาจมาไกลถึงอัฟกานิสถานหรือเอเชียกลาง ก่อนมีสำริดดีบุก ช่างใช้ทองแดงผสมสารหนูซึ่งเป็นพิษต่อคนหลอม','Bronze is copper alloyed with about a tenth tin, harder than pure copper. Mesopotamia had neither metal and imported both; tin may have come from as far as Afghanistan or Central Asia. Before tin bronze, smiths used arsenical copper, which poisoned those who smelted it.'),
 o:[opt(X('ใช้ทองแดงผสมสารหนูแบบเก่า','Use the old arsenic copper'),S=>{fx({h:-6,cr:3});S.yr+=.01;return X('ควันจากเตาทำให้คุณไอทั้งคืน แต่ของที่หล่อแข็งพอ','The furnace fumes leave you coughing all night, but the castings are hard enough.')}),
    opt(X('รอ และหลอมของเก่ามาใช้ใหม่','Wait, and remelt old pieces'),S=>{fx({kn:3,f:-2});return X('คุณหลอมขวานหักและเข็มเก่าจนได้สำริดพอทำงานหนึ่งชิ้น','You melt broken axes and old pins until you have bronze enough for one job.')})]},
{id:'k4_pollinate',a:[14,60],w:3,ch:4,cond:S=>S.car==='gardener',t:X('ผสมเกสรอินทผลัม','Pollinating the palms'),
 x:X('คนสวนแก่สอนให้คุณปีนขึ้นต้นอินทผลัมตัวผู้ ตัดช่อดอกมาผูกไว้ที่ต้นตัวเมีย','An old gardener teaches you to climb the male date palms, cut their flowers and tie them into the female trees.'),
 n:X('ชาวเมโสโปเตเมียผสมเกสรอินทผลัมด้วยมือมาตั้งแต่สมัยโบราณ ภาพสลักอัสซีเรียแสดงฉากนี้ และกฎหมายฮัมมูราบีมีหลายข้อเกี่ยวกับสวนอินทผลัม โดยคนสวนได้ส่วนแบ่งจากผลผลิต','Mesopotamians pollinated date palms by hand from early times; Assyrian reliefs show it, and several of Hammurabi’s laws concern date orchards, with the gardener taking a share of the harvest.'),
 o:[opt(X('ปีนขึ้นไปเอง','Climb up yourself'),S=>{if(rnd()<.12){fx({h:-10});S.inj=1;return X('ทางใบอินทผลัมหักใต้เท้า คุณตกลงมาขาเคล็ด','A frond snaps underfoot and you fall, twisting your leg.')}addItem('dates',2);fx({sv:3,kn:3});return X('ปีนั้นต้นอินทผลัมของคุณออกลูกดกจนกิ่งโน้ม','That year your palms bear so heavily the branches bow.')}),
    opt(X('จดว่าต้นไหนผสมแล้ว','Keep track of which trees are done'),S=>{fx({kn:4});return X('คุณผูกด้ายสีไว้ที่ต้นที่ผสมแล้ว คนสวนแก่ยกนิ้วให้','You tie a coloured thread on each finished tree, and the old gardener nods approval.')})]},
{id:'k4_battle',a:[16,50],w:3,ch:4,cond:S=>S.car==='soldier'&&S.clv>=1,t:X('แถวโล่','The shield wall'),
 x:X('กองทัพศัตรูอยู่ตรงหน้า หัวหน้าสั่งให้ทุกคนยืนชิดกันหลังโล่ แล้วยื่นหอกออกไป','The enemy army stands before you. Your captain orders everyone to close up behind their shields and push their spears forward.'),
 n:RNOTE4.lag,
 o:[opt(X('ยืนอยู่แถวหน้า','Hold the front rank'),S=>{if(rnd()<.6){fx({p:6,sv:2});S.ag+=2;return X('แถวของคุณไม่แตก ศัตรูถอย','Your rank does not break, and the enemy falls back.')}S.inj=1;fx({h:-15});return X('หอกของศัตรูทะลุโล่และบาดไหล่คุณ','An enemy spear pierces your shield and cuts your shoulder.')}),
    opt(X('ดูแลเพื่อนที่บาดเจ็บข้างหลัง','Tend the wounded behind the line'),S=>{fx({so:4,b:4});return X('คุณลากเพื่อนสามคนออกจากสนามรบ','You drag three friends off the field.')})]},
];
